// Devuelve una ficha normalizada sin importar si la fuente es CDS_DATA (rica)
// o ESSLO_DATA (liviana) — para que CollegeProfileCard no tenga que saber de dónde vino.
// Por qué no hay ficha: distingue las universidades de afuera de EE.UU. (no están en las bases federales) de las que todavía no cargamos.
function noFichaReason(school, base) {
  const txt = `${school} ${(base && (base.State || "")) || ""}`;
  if (/\((canad|canada)\)/i.test(String(base && base.State || "")) || /canad|british columbia|ontario|alberta|saskatchewan|quebec|england|united kingdom/i.test(txt)) {
    return "Es una institución de fuera de EE.UU.: no figura en las bases federales de admisión y costos. Consultá los requisitos para estudiantes internacionales en su sitio oficial.";
  }
  return "Todavía no tenemos datos de admisión y costo para esta institución (suele pasar con colleges chicos o recién fusionados). Consultalos en su sitio oficial.";
}
// Ficha mínima con datos oficiales del College Scorecard, para las universidades que no tienen CDS ni ESSLO.
function scorecardFicha(school) {
  const d = scorecardFor(school);
  if (!d) return null;
  return {
    admit_rate: d.a || null, sat_range: d.s || null, act_range: d.t || null,
    cost_in_state_usd: d.ci || null, cost_out_state_usd: d.co || null, cost_of_attendance_usd: d.co || d.ci || null,
    undergrad_enrollment: d.e || null, grad_rate: d.g || null, website: d.w || null,
    majors_offered_ABET: [], need_policy: "", verified: true, logo: null, source: "scorecard",
  };
}
function getSchoolFicha(school) {
  const rich = CDS_DATA[school];
  if (rich) return { ...rich, source: "cds" };
  const light = ESSLO_DATA[school];
  if (!light) { const sc = scorecardFicha(school); if (sc) return sc; }
  if (light) {
    const needText = light.need_met
      ? `En promedio cubre ${light.need_met} de la necesidad demostrada. ${light.receiving_aid ? `${light.receiving_aid} de los estudiantes reciben algún tipo de ayuda` : ""}${light.avg_package ? `, paquete promedio de USD ${light.avg_package}/año` : ""}.`
      : "Sin dato de política de ayuda financiera verificado todavía.";
    return {
      ...light,
      majors_offered_ABET: [],
      need_policy: needText,
      verified: true,
      source: "esslo",
    };
  }
  return null;
}

// nunca matchea contra "Chemical Engineering" en el Common Data Set (bug
// real detectado: Delaware con una argentina real en el roster no
