// ---- Mi correo ----
// Escribir mails hiper personalizados (motor único: composeEmail) y llevar el registro de envíos.
// El registro se anota cuando la atleta toca un botón de envío (abrir en Gmail/Outlook/Mail o copiar):
// el sitio no puede ver si el mail finalmente salió ni si el coach respondió, por eso el estado
// ("sin respuesta", "respondió"...) lo marca ella.
function daysSince(isoDate) {
  return Math.floor((Date.now() - new Date(isoDate).getTime()) / (1000 * 60 * 60 * 24));
}

function removeOutreach(university) {
  const log = readOutreachLog();
  const entry = log[university];
  if (!entry) return;
  delete log[university];
  writeOutreachLog(log);
  try {
    const n = parseInt(localStorage.getItem("rr_outreach_count") || "0", 10);
    lsSetSynced("rr_outreach_count", String(Math.max(0, n - (entry.timesContacted || 1))));
  } catch (e) { /* modo privado */ }
}

// Qué datos propios tiene sentido pedir en cada tipo de mail.
const MAIL_FACTS_BY_KIND = {
  first: ["referral", "watched", "met", "result", "avail"],
  followup: ["referral", "watched", "met", "result"],
  update: ["result"],
  reply: ["answer", "avail"],
  thanks: ["result"],
  offer: [],
  close: [],
  call: ["avail"],
  checkin: ["result", "watched"],
  refs: ["referral"],
  time: ["deadline"],
  decline: ["reason"],
  commit: [],
};
function mailKindLabel(kind, stage) {
  if (kind !== "followup" || !stage) return (MAIL_KINDS[kind] || MAIL_KINDS.first).label;
  return stage >= MAX_FOLLOWUPS ? `Seguimiento ${stage} de ${MAX_FOLLOWUPS} (último intento)` : `Seguimiento ${stage} de ${MAX_FOLLOWUPS}`;
}
function shortDate(iso) { try { return new Date(iso).toLocaleDateString("es-AR", { day: "numeric", month: "short" }); } catch (e) { return ""; } }

function MailComposer({ profile, log, pick, onTracked }) {
  const results = useMemo(() => { try { return runMatch(profile); } catch (e) { return []; } }, [profile]);
  const [favs] = useFavorites();
  const catalog = useMemo(() => Array.from(new Set(PROGRAMS_ALL_SPORTS.filter((p) => p.sport === profile.sport && (!p.Gender || p.Gender === profile.gender)).map((p) => p.School))).sort(), [profile.sport, profile.gender]);
  const groups = useMemo(() => {
    const seen = new Set();
    const uniq = (arr) => arr.filter((u) => u && !seen.has(u) && (seen.add(u), true));
    return [
      { label: "Tu top 10", items: uniq(results.map((r) => r.university)) },
      { label: "Mi lista ★", items: uniq(favs) },
      { label: "Ya contactadas", items: uniq(Object.keys(log)) },
    ].filter((g) => g.items.length > 0);
  }, [results, favs, log]);

  const [university, setUniversity] = useState(() => {
    if (pick && pick.university) return pick.university;
    const fresh = results.find((r) => !log[r.university]);
    return (fresh || results[0] || {}).university || "__other";
  });
  const [other, setOther] = useState("");
  const [kind, setKind] = useState(() => (pick && pick.kind) || nextOutreachStep(log[university]).kind);
  const [lang, setLangState] = useState(readEmailLang);
  const [emailTo, setEmailTo] = useState("");
  const [draft, setDraft] = useState({ subject: "", body: "" });
  const [notice, setNotice] = useState("");
  const [hookChoice, setHookChoice] = useState(null); // null = automático · "none" = sin gancho · id = elegido a mano
  const [facts, setFacts] = useState({});
  const [sentNote, setSentNote] = useState("");
  // IA (paso 2): mejora el borrador del tipo de mail elegido o responde el mensaje que pegó la atleta.
  const [tone, setTone] = useState("profesional");
  const [aiBusy, setAiBusy] = useState(false);
  const [aiErr, setAiErr] = useState("");
  const [aiTodo, setAiTodo] = useState([]);
  const [aiUsed, setAiUsed] = useState(false);
  const [coachMsg, setCoachMsg] = useState({ msg: "", subject: "" });

  useEffect(() => { if (pick) { setUniversity(pick.university); setKind(pick.kind); setHookChoice(null); } }, [pick]);

  const target = university === "__other" ? (catalog.includes(other.trim()) ? other.trim() : "") : university;
  const rLike = useMemo(() => results.find((r) => r.university === target) || null, [results, target]);
  // Foto del registro al elegir universidad y tipo: si se actualizara al tocar "Abrir en Gmail",
  // el borrador cambiaría solo (pasaría de "seguimiento 1" a "seguimiento 2") justo después de enviarlo.
  const selKey = `${target}|${kind}|${pick ? pick.nonce : ""}`;
  const snap = useRef({ key: null, entry: null });
  if (snap.current.key !== selKey) snap.current = { key: selKey, entry: (target && log[target]) || null };
  const entrySnap = snap.current.entry;
  const step = nextOutreachStep(entrySnap);

  useEffect(() => { setHookChoice(null); }, [target]);
  useEffect(() => { setFacts(target ? readMailFacts(target) : {}); setSentNote(""); }, [target, kind]);

  const email = useMemo(
    () => (target ? composeEmail({ profile, university: target, r: rLike, kind, lang, contactEntry: entrySnap, hook: hookChoice, facts }) : null),
    [profile, target, rLike, kind, lang, selKey, hookChoice, facts]
  );
  useEffect(() => { if (email) setDraft({ subject: email.subject, body: email.body }); setAiUsed(false); setAiTodo([]); setAiErr(""); }, [email ? email.subject : "", email ? email.body : ""]);
  useEffect(() => { setCoachMsg((target && readJSON("rr_coach_msgs", {})[target]) || { msg: "", subject: "" }); }, [target]);
  const saveCoachMsg = (next) => {
    setCoachMsg(next);
    const all = readJSON("rr_coach_msgs", {});
    if (next.msg.trim() || next.subject.trim()) all[target] = next; else delete all[target];
    writeJSON("rr_coach_msgs", all);
  };
  const genAI = async () => {
    if (!email) return;
    if (kind === "reply" && !coachMsg.msg.trim()) { setAiErr("Pegá primero el mensaje del coach: la IA lo usa para responder cada cosa que te preguntó."); return; }
    setAiBusy(true); setAiErr("");
    try {
      const p = profile || {};
      const hk = email.hook ? email.hooks.find((h) => h.id === email.hook) : null;
      const res = await fetch("/api/generate-email", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({
        kind, stage: email.stage || null, tone, lang,
        profile: aiProfile(p),
        program: { university: target, division: email.division || null, coachName: email.coachName || null },
        hook: hk ? `${hk.label}: ${hk.text}` : "",
        facts: cleanMailFacts(facts),
        coachMessage: kind === "reply" ? coachMsg.msg : "", coachSubject: kind === "reply" ? coachMsg.subject : "",
        baseDraft: `${email.subject}\n\n${email.body}`,
      }) });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || !data.subject) throw new Error((data.error || `No se pudo generar el mail (error ${res.status}).`) + (data.detail ? ` Detalle: ${data.detail}` : ""));
      setDraft({ subject: data.subject, body: data.body });
      setAiTodo(Array.isArray(data.todo) ? data.todo : []);
      setAiUsed(true);
      try { window.posthog && window.posthog.capture("mail_generado_ia", { kind, tone, lang, con_mensaje_coach: kind === "reply" }); } catch (e) { /* sin analítica */ }
    } catch (e) { setAiErr(String(e.message || e)); }
    setAiBusy(false);
  };
  useEffect(() => { setEmailTo(email ? email.to : ""); setNotice(""); }, [target]);

  const changeUniversity = (value) => {
    setUniversity(value);
    setKind(nextOutreachStep(value !== "__other" ? log[value] : null).kind);
  };
  const changeLang = (value) => { setLangState(value); writeEmailLang(value); };
  const setFact = (key, value) => {
    const next = { ...facts, [key]: value };
    setFacts(next);
    writeMailFacts(target, next);
    if (key === "referral" || key === "watched" || key === "met") setHookChoice(null); // un dato propio nuevo pasa a ser el gancho
  };

  const urls = composeUrls({ to: emailTo, subject: draft.subject, body: draft.body });
  const track = () => {
    if (!email) return;
    if (emailTo.trim() && emailTo.trim() !== (email.to || "")) saveCoachEmail(target, emailTo);
    trackOutreach({ university: target, sport: profile.sport, coachName: email.coachName, kind, hook: email.hook, lang, ai: aiUsed, subject: draft.subject });
    if (kind === "reply") saveCoachMsg({ msg: "", subject: "" }); // ya respondido: no queda pegado para la próxima
    // Los datos propios que salieron en este mail ya se usaron: no se repiten solos en el próximo.
    const rest = { ...facts };
    (MAIL_FACTS_BY_KIND[kind] || []).forEach((k) => { delete rest[k]; });
    writeMailFacts(target, rest);
    const after = nextOutreachStep(readOutreachLog()[target]);
    setSentNote(`Anotado en Mis envíos como "${mailKindLabel(kind, email.stage)}"${email.hook ? ` con el gancho "${HOOK_LABELS[email.hook]}"` : ""}. ${after.text}`);
    onTracked();
  };
  const fullText = `${lang === "en" ? "Subject" : "Asunto"}: ${draft.subject}\n\n${draft.body}`;
  const chipStyle = { alta: "alta", media: "media", baja: "baja" };
  const history = outreachMessages(entrySnap);
  const factKeys = MAIL_FACTS_BY_KIND[kind] || [];
  const hooksOn = email ? email.hooks.filter((h) => h.available) : [];
  const hooksOff = email ? email.hooks.filter((h) => !h.available && h.reason) : [];

  return (
    <div className="rm-mail" id="rm-mail-composer">
      <div className="rm-mail-controls">
        <label className="rm-mail-field">
          <span>¿A qué universidad le escribís?</span>
          <select value={university} onChange={(e) => changeUniversity(e.target.value)}>
            {groups.map((g) => (
              <optgroup key={g.label} label={g.label}>{g.items.map((u) => <option key={u} value={u}>{u}{log[u] ? " — ya contactada" : ""}</option>)}</optgroup>
            ))}
            <option value="__other">Otra universidad…</option>
          </select>
        </label>
        {university === "__other" && (
          <label className="rm-mail-field">
            <span>Buscá la universidad ({profile.sport})</span>
            <input list="rm-mail-catalog" value={other} onChange={(e) => setOther(e.target.value)} placeholder="Escribí el nombre y elegí de la lista" />
            <datalist id="rm-mail-catalog">{catalog.map((u) => <option key={u} value={u} />)}</datalist>
          </label>
        )}
        <label className="rm-mail-field">
          <span>Tipo de mail</span>
          <select value={kind} aria-label="Tipo de mail" onChange={(e) => { setKind(e.target.value); setHookChoice(null); }}>
            {Object.entries(MAIL_KINDS).map(([k, v]) => <option key={k} value={k}>{v.label}{target && k === step.kind ? " — sugerido" : ""}</option>)}
          </select>
        </label>
        <div className="rm-mail-field">
          <span>Idioma del mail</span>
          <div className="rm-seg" role="group" aria-label="Idioma del mail">
            <button type="button" className={lang === "es" ? "on" : ""} onClick={() => changeLang("es")}>Español</button>
            <button type="button" className={lang === "en" ? "on" : ""} onClick={() => changeLang("en")}>English</button>
          </div>
        </div>
      </div>
      <p className="rm-today-note" style={{ marginTop: 6 }}>Los mails salen en English por defecto porque los coaches de EE.UU. leen en inglés. Si el programa es hispanohablante, pasalo a Español.</p>

      {!email ? (
        <p className="rm-hint" style={{ marginTop: 16 }}>Elegí una universidad de la lista para generar el mail.</p>
      ) : (
        <div className="rm-mail-grid">
          <div className="rm-mail-left">
            <div className="rm-mail-headline">
              <b>{target}</b>
              <span>{email.division || "división sin dato"}{rLike ? ` · Score ${rLike.score}/100` : ""}</span>
              <span className="rm-vacancy-chip media">{mailKindLabel(kind, email.stage)}</span>
              {email.confidence && <span className={`rm-vacancy-chip ${chipStyle[email.confidence]}`}>Vacante proyectada: {email.confidence}</span>}
            </div>
            <p className={`rm-mail-step ${step.due ? "due" : ""}`}><b>Qué toca con este programa:</b> {step.text}{step.kind !== kind && !step.exhausted ? <> <button type="button" className="rm-btn-inline" onClick={() => { setKind(step.kind); setHookChoice(null); }}>Usar "{MAIL_KINDS[step.kind].label}"</button></> : null}</p>
            <p className={`rm-mail-timing ${email.calendar.kind === "restricted" ? "warn" : "ok"}`}>{email.calendar.kind === "restricted" ? "🟡 " : "🟢 "}{email.calendar.uiText}</p>

            {history.length > 0 && (
              <details className="rm-mail-details">
                <summary>Lo que ya le mandaste ({history.length} envío{history.length === 1 ? "" : "s"})</summary>
                <ul>
                  {history.map((m, i) => (
                    <li key={i}>{shortDate(m.at)} · {mailKindLabel(m.kind, m.stage)}{m.hook ? ` · gancho: ${HOOK_LABELS[m.hook] || m.hook}` : m.legacy ? " · sin detalle (envío anterior a esta versión)" : ""}{m.ai ? " · con IA" : ""}</li>
                  ))}
                </ul>
              </details>
            )}

            {email.carriesHook && (
              <div className="rm-mail-field">
                <span>Gancho de este mail — uno solo: el motivo concreto por el que le escribís a este coach</span>
                {hooksOn.length === 0 ? (
                  <p className="rm-today-note">No encontramos un gancho con datos reales para este programa. Sumá un dato tuyo abajo: es lo que más diferencia a un mail.</p>
                ) : (
                  <div className="rm-hooks" role="group" aria-label="Gancho del mail">
                    {hooksOn.map((h) => (
                      <button type="button" key={h.id} className={`rm-hook ${email.hook === h.id ? "on" : ""}`} aria-pressed={email.hook === h.id} onClick={() => setHookChoice(h.id)}>
                        <b>{h.label}</b>
                        <small>{h.source}{h.usedAt ? ` · ya lo usaste el ${shortDate(h.usedAt)}` : ""}</small>
                      </button>
                    ))}
                    <button type="button" className={`rm-hook ${!email.hook ? "on" : ""}`} aria-pressed={!email.hook} onClick={() => setHookChoice("none")}><b>Sin gancho</b><small>Mail más corto</small></button>
                  </div>
                )}
                {hooksOff.length > 0 && (
                  <details className="rm-mail-details">
                    <summary>Por qué no aparecen los otros ganchos ({hooksOff.length})</summary>
                    <ul>{hooksOff.map((h) => <li key={h.id}><b>{h.label}:</b> {h.reason}</li>)}</ul>
                  </details>
                )}
              </div>
            )}

            {kind === "reply" && (
              <div className="rm-mail-field">
                <span>Pegá el mensaje del coach (la IA responde cada pregunta con tus datos; lo que no sepa lo deja marcado entre corchetes)</span>
                <input value={coachMsg.subject} onChange={(e) => saveCoachMsg({ ...coachMsg, subject: e.target.value })} placeholder="Asunto del mail del coach (opcional: la respuesta va con «Re:» en el mismo hilo)" />
                <textarea className="rm-compose-text" rows={6} value={coachMsg.msg} onChange={(e) => saveCoachMsg({ ...coachMsg, msg: e.target.value })} placeholder="Hi Sofía, thanks for reaching out. Could you send us your transcripts and your full game film? When do you take the SAT?" />
              </div>
            )}

            {factKeys.length > 0 && (
              <details className="rm-mail-details" open={factKeys.some((k) => facts[k]) || kind === "reply" || kind === "update"}>
                <summary>Sumá un dato tuyo (opcional): se integra solo al mail</summary>
                <p className="rm-today-note">Escribilo en el idioma del mail ({lang === "en" ? "English" : "Español"}), sin punto final. Solo cosas ciertas: el coach las puede comprobar.</p>
                {factKeys.map((k) => {
                  const f = MAIL_FACT_FIELDS[k];
                  return (
                    <label className="rm-mail-field" key={k}>
                      <span>{f.label}</span>
                      {f.long
                        ? <textarea className="rm-compose-text" rows={4} value={facts[k] || ""} onChange={(e) => setFact(k, e.target.value)} placeholder={lang === "en" ? "Yes, I can send my transcripts this week. My SAT is scheduled for December 6." : "Sí, puedo enviar mi analítico esta semana. Rindo el SAT el 6 de diciembre."} />
                        : <input value={facts[k] || ""} onChange={(e) => setFact(k, e.target.value)} placeholder={lang === "en" ? f.en : f.es} />}
                    </label>
                  );
                })}
              </details>
            )}

            <label className="rm-mail-field">
              <span>Email del coach {email.to ? "(ya lo tenemos)" : "(pegalo y lo guardamos)"}</span>
              <div className="rm-mail-inline">
                <input type="email" value={emailTo} onChange={(e) => setEmailTo(e.target.value)} placeholder="coach@universidad.edu" />
                <button type="button" className="rm-btn-inline" onClick={() => { saveCoachEmail(target, emailTo); setNotice("Email del coach guardado en este navegador."); }}>Guardar</button>
              </div>
            </label>
            {notice && <p className="rm-today-note" style={{ color: "var(--field-dark)", fontWeight: 600 }}>{notice}</p>}

            {aiErr && <p className="rm-today-note" style={{ color: "#b3261e" }}>⚠ {aiErr}</p>}
            {aiUsed && <p className="rm-today-note">Borrador escrito con IA a partir de tus datos{kind === "reply" ? " y del mensaje del coach" : ""}, con el gancho y el tipo de mail elegidos. Revisalo antes de mandarlo: vos firmás el mail.</p>}
            {aiTodo.length > 0 && (
              <details className="rm-mail-details" open>
                <summary>Para completar o revisar ({aiTodo.length})</summary>
                <ul>{aiTodo.map((t, i) => <li key={i}>{t}</li>)}</ul>
              </details>
            )}

            <label className="rm-mail-field"><span>Asunto</span><input value={draft.subject} onChange={(e) => setDraft({ ...draft, subject: e.target.value })} /></label>
            <label className="rm-mail-field"><span>Mail (podés editarlo antes de enviarlo)</span>
              <textarea className="rm-compose-text" rows={kind === "first" ? 18 : 12} value={draft.body} onChange={(e) => setDraft({ ...draft, body: e.target.value })} />
            </label>
            {email.missing.length > 0 && !aiUsed && (
              <details className="rm-mail-details" open>
                <summary>Antes de enviar ({email.missing.length})</summary>
                <ul>{email.missing.map((m, i) => <li key={i}>{m}</li>)}</ul>
              </details>
            )}
            <div className="rm-compose-actions">
              <a className="rm-compose-btn" href={urls.gmailUrl} target="_blank" rel="noreferrer" onClick={track}>Abrir en Gmail</a>
              <a className="rm-compose-btn" href={urls.outlookUrl} target="_blank" rel="noreferrer" onClick={track}>Abrir en Outlook</a>
              <a className="rm-compose-btn" href={urls.mailtoUrl} onClick={track}>Abrir en Mail (iCloud/Apple/otro)</a>
              <button type="button" className="rm-compose-btn" onClick={() => { try { navigator.clipboard.writeText(fullText).catch(() => {}); } catch (e) { /* sin portapapeles */ } track(); }}>Copiar texto</button>
            </div>
            {sentNote && <p className="rm-mail-step due" role="status">✓ {sentNote}</p>}
            <p className="rm-today-note">Se abre en tu propio cliente de mail y lo mandás vos, con tu cuenta: nunca vemos ni guardamos tu contraseña. Al tocar un botón queda anotado en <b>Mis envíos</b> con su tipo y su gancho; no podemos ver si finalmente lo enviaste.</p>
            <button type="button" className="rm-btn-inline" onClick={() => downloadFollowUpICS(profile, { university: target }, email.coachName)}>📅 Agendar recordatorio para reescribirle a este coach en 10 días</button>
          </div>

        </div>
      )}
    </div>
  );
}

function MailPage({ profile, setStage, embedded, initialPick }) {
  const [log, setLog] = useState(() => readOutreachLog());
  const [pick, setPick] = useState(initialPick || null);
  const entries = Object.values(log).sort((a, b) => new Date(b.lastContact) - new Date(a.lastContact));

  const updateStatus = (university, status) => {
    setLog((prev) => {
      const next = withOutreachStatus(prev, university, status);
      writeOutreachLog(next);
      return next;
    });
  };
  const saveNote = (university, notes) => {
    setLog((prev) => { const next = withOutreachNote(prev, university, notes); writeOutreachLog(next); return next; });
  };
  const remove = (university) => { removeOutreach(university); setLog(readOutreachLog()); };
  const followUp = (university) => {
    setPick({ university, kind: nextOutreachStep(log[university]).kind, nonce: Date.now() });
    const el = document.getElementById("rm-mail-composer");
    if (el && el.scrollIntoView) el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  const needsFollowUp = entries.filter((e) => followUpDue(e));
  const responded = entries.filter((e) => ["respondio", "visita", "oferta"].includes(e.status));
  const [view, setView] = useState("tablero");
  const [favorites] = useState(() => readFavorites());
  const writeFirst = (university) => {
    setPick({ university, kind: "first", nonce: Date.now() });
    const el = document.getElementById("rm-mail-composer");
    if (el && el.scrollIntoView) el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  return (
    <div className={embedded ? "" : "rm-wrap"} style={embedded ? {} : { paddingTop: 40, paddingBottom: 60 }}>
      <h2 className="rm-condensed">Mi correo</h2>
      <p className="rm-hint">Acá escribís tus mails a los coaches y llevás el registro de a quién le escribiste. El sitio elige el tipo de mail según en qué punto estás con cada programa (primer contacto, seguimiento, novedad, respuesta, oferta) y lo arma con lo que sabe: tu perfil, las búsquedas que publicó ese coach, las vacantes proyectadas para tu año de ingreso, compatriotas en el plantel o en el staff, y los datos que sumes vos. Cada mail lleva un solo gancho, y el siguiente nunca repite el anterior.</p>

      <p className="rm-exam-note" style={{ marginTop: 8 }}>Cada mail es un borrador sugerido: revisalo, adaptalo y envialo desde tu propia cuenta. Smartrecruit no envía correos ni se comunica con entrenadores por vos.</p>
      {profile ? (
        <MailComposer profile={profile} log={log} pick={pick} onTracked={() => setLog(readOutreachLog())} />
      ) : (
        <div className="rm-alert" style={{ marginTop: 16 }}>
          Para generar mails personalizados primero necesitás tu perfil. <button className="rm-btn-inline" onClick={() => setStage("form")}>Armar mi perfil →</button>
        </div>
      )}

          {(() => {
        const today = coachesForToday(entries);
        if (!today.length) return null;
        return (
          <div className="rm-alert" style={{ marginTop: 28 }}>
            <b>Para atender hoy:</b>
            <ol style={{ margin: "6px 0 0", paddingLeft: 20 }}>
              {today.map(({ e, step }) => (
                <li key={e.university} style={{ marginBottom: 4 }}>
                  <b>{e.university}</b> — {step.text}{" "}
                  {profile && <button type="button" className="rm-btn-inline" onClick={() => followUp(e.university)}>Escribir →</button>}
                </li>
              ))}
            </ol>
          </div>
        );
      })()}
      <h3 className="rm-condensed" style={{ fontSize: 20, marginTop: 34 }}>Mi embudo</h3>
      <p className="rm-today-note">Cada universidad es una tarjeta. Arrastrala a la columna que corresponde (o usá el selector en el celular) cuando el coach responda, te llame o te haga una oferta.</p>
      <div className="rm-view-toggle" role="tablist">
        <button type="button" role="tab" aria-selected={view === "tablero"} className={view === "tablero" ? "on" : ""} onClick={() => setView("tablero")}>Tablero</button>
        <button type="button" role="tab" aria-selected={view === "metricas"} className={view === "metricas" ? "on" : ""} onClick={() => setView("metricas")}>Métricas</button>
        <button type="button" role="tab" aria-selected={view === "lista"} className={view === "lista" ? "on" : ""} onClick={() => setView("lista")}>Lista</button>
      </div>
      {view === "tablero" && <OutreachKanban log={log} favorites={favorites} onMove={updateStatus} onWrite={writeFirst} />}
      {view === "metricas" && (entries.length ? <OutreachMetrics log={log} /> : <p className="rm-today-note">Las métricas aparecen cuando le escribas al primer coach.</p>)}
      {view === "lista" && (entries.length === 0 ? (
        <p className="rm-today-note">Todavía no tocaste ningún botón de envío. Cuando lo hagas, cada universidad queda registrada acá.</p>
      ) : (
        <>
          <div className="rm-recruit-fit-summary" style={{ paddingLeft: 0, marginTop: 10 }}>
            <span className="rm-fit-chip" style={{ background: "#eaf1fa", color: "#2f6fb3" }}>{entries.length} contactadas</span>
            <span className="rm-fit-chip" style={{ background: "#fdeceb", color: "#b3401a" }}>{needsFollowUp.length} necesitan seguimiento</span>
            <span className="rm-fit-chip" style={{ background: "#eaf6ee", color: "#1f7a3f" }}>{responded.length} respondieron</span>
          </div>
          <div className="rm-catalog-list" style={{ marginTop: 20 }}>
            {entries.map((e) => {
              const days = daysSince(e.lastContact);
              const stale = followUpDue(e);
              const step = nextOutreachStep(e);
              const msgs = outreachMessages(e);
              const lastMsg = msgs[msgs.length - 1] || null;
              return (
                <div className="rm-catalog-row" key={e.university} style={{ cursor: "default" }}>
                  <div className="rm-catalog-row-main">
                    <b>{e.university}</b>
                    {e.coachName && <span style={{ fontSize: 12, color: "var(--ink-soft)" }}>— {e.coachName}</span>}
                    {stale && <span className="rm-badge-cds" style={{ background: "#fdeceb", color: "#b3401a", borderColor: "#b3401a" }}>SEGUIMIENTO</span>}
                    {(() => { const h = coachHeat(e); return <span className="rm-fit-chip" title="Qué tan avanzado está el vínculo, según el estado y las fechas" style={{ background: h.bg, color: h.color }}>{h.label}</span>; })()}
                  </div>
                  <div className="rm-catalog-row-meta">
                    {e.sport} · {e.timesContacted} envío{e.timesContacted === 1 ? "" : "s"} · último hace {days === 0 ? "hoy" : `${days} día${days === 1 ? "" : "s"}`} ({new Date(e.firstContact).toLocaleDateString("es")} → {new Date(e.lastContact).toLocaleDateString("es")})
                    {lastMsg && !lastMsg.legacy ? ` · último: ${mailKindLabel(lastMsg.kind, lastMsg.stage)}${lastMsg.hook ? `, gancho "${HOOK_LABELS[lastMsg.hook] || lastMsg.hook}"` : ""}` : ""}
                  </div>
                  <div className="rm-catalog-row-meta" style={{ flexBasis: "100%", color: step.due ? "#b3401a" : undefined, fontWeight: step.due ? 600 : undefined }}>{step.text}</div>
                  <div style={{ marginTop: 8, display: "flex", gap: 14, alignItems: "center", flexWrap: "wrap" }}>
                    <select value={e.status} onChange={(ev) => updateStatus(e.university, ev.target.value)} style={{ padding: "6px 10px", fontSize: 13, border: "2px solid var(--line)" }}>
                      {Object.entries(OUTREACH_STATUS_LABELS).map(([k, label]) => <option key={k} value={k}>{label}</option>)}
                    </select>
                    {profile && <button type="button" className="rm-btn-inline" onClick={() => followUp(e.university)}>Escribir {MAIL_KINDS[step.kind].label.toLowerCase()} →</button>}
                    <button type="button" className="rm-btn-inline" style={{ color: "var(--ink-soft)" }} onClick={() => remove(e.university)}>Quitar del registro</button>
                  </div>
                  <details style={{ flexBasis: "100%", marginTop: 8 }} open={!!e.notes}>
                    <summary style={{ cursor: "pointer", fontSize: 13, color: "var(--ink-soft)" }}>Notas sobre este coach{e.notes ? " ✓" : ""}</summary>
                    <textarea aria-label={`Notas sobre ${e.university}`} defaultValue={e.notes || ""} maxLength={600} rows={3} placeholder="Qué te dijo, qué te pidió (video, notas, llamada), fechas de visita…" onBlur={(ev) => { if (ev.target.value !== (e.notes || "")) saveNote(e.university, ev.target.value); }} style={{ width: "100%", marginTop: 6, padding: 8, fontSize: 13, border: "2px solid var(--line)", fontFamily: "inherit", boxSizing: "border-box" }} />
                  </details>
                </div>
              );
            })}
          </div>
        </>
      ))}
      <p className="rm-today-note" style={{ marginTop: 20 }}>Si iniciaste sesión con tu cuenta, el registro se guarda en tu cuenta y lo ves desde cualquier dispositivo; si no, queda solo en este navegador. "Quitar del registro" es para los mails que abriste pero no mandaste.</p>
    </div>
  );
}

/* ---------------------------------------------------------------
   FIT SCORE — compatibilidad deportiva, académica y financiera con cada universidad
   Deportivo: el puntaje del ranking (búsqueda publicada, vacante proyectada, nivel vs. plantel).
   Académico: si ofrece tu carrera (CDS, College Scorecard o IPEDS) y tu GPA contra el de referencia.
   Financiero: tipo de beca de la división, cuánto reparte por deportista (EADA) y costo.
--------------------------------------------------------------- */
function computeFitScore(r, profile) {
  const clamp = (v) => Math.max(0, Math.min(100, Math.round(v)));
  const athletic = clamp(r.score);
  const athleticNote = r.eadaOnly ? "sin búsqueda ni roster: solo datos oficiales" : r.vacancy ? "búsqueda, vacante proyectada y nivel vs. plantel" : r.partialRoster ? "estadísticas del plantel, sin vacante proyectada" : "búsqueda publicada por el coach";

  const fit = r.academicFit || { status: "no_verificado" };
  let career = 25, careerNote = "carrera sin confirmar";
  if (fit.status === "confirmado_si") { career = 50; careerNote = "ofrece tu carrera"; }
  else if (fit.status === "no_verificado" && fit.related) { career = 35; careerNote = "tiene una carrera afín"; }
  else if (fit.status === "ipeds_no") { career = 5; careerNote = "no registra tu carrera"; }
  else if (fit.status === "confirmado_no") { career = 0; careerNote = "no ofrece tu carrera"; }
  const ncsa = SCHOOL_PROFILES_NCSA[r.university];
  const bench = (ncsa && parseFloat(ncsa.avg_freshman_gpa)) || ACADEMIC_GPA_BENCHMARK[r.division] || (String(r.division || "").startsWith("NJCAA") ? 2.3 : 3.0);
  let gpaPts = 25, gpaNote = "sin GPA convertido";
  if (profile && typeof profile.gpa4 === "number" && !Number.isNaN(profile.gpa4)) {
    const diff = profile.gpa4 - bench;
    gpaPts = diff >= 0 ? 50 : diff >= -0.3 ? 35 : diff >= -0.6 ? 20 : 8;
    gpaNote = `tu GPA ${profile.gpa4.toFixed(2)} vs. ${bench.toFixed(1)} de referencia`;
  }
  const adm = admissionOdds(r.university, r.division, profile);
  const admPts = { alta: 30, media: 20, baja: 8, "muy baja": 0 }[adm.level] ?? 15;
  const academic = clamp(career * 0.8 + gpaPts * 0.6 + admPts);

  const sch = r.scholarship || scholarshipInfo(r.division, profile.sport, profile.gender);
  const mid = sch.pctLow != null && sch.pctHigh != null ? (sch.pctLow + sch.pctHigh) / 2 : 30;
  const e = eadaFor(r.university);
  const g = profile.gender === "F" ? 1 : 0;
  let fin = mid * 0.5, finNotes = [`${sch.tipo}`];
  if (e) {
    if (e.ath[g] > 0 && e.aid[g] === 0) { fin = Math.min(fin, 10); finNotes = ["no da becas deportivas a tu rama"]; }
    else {
      const pct = eadaAidPercentile(e, profile.gender);
      if (pct != null) { fin += pct * 35; finNotes.push(`reparte más que el ${Math.round(pct * 100)}% de su división`); }
    }
    if (e.lvl === 2) { fin += 10; finNotes.push("college de 2 años, más barato"); }
    else if (e.ctl === 1) { fin += 5; finNotes.push("pública"); }
  }
  const card = schoolCardData(r.university, null);
  if (card && card.tuition) {
    if (card.tuition > 50000) { fin -= 10; finNotes.push("matrícula alta"); }
    else if (card.tuition < 20000) { fin += 5; finNotes.push("matrícula baja"); }
  }
  const cov = estimateCoverage(r.university, r.division, profile.sport, profile.gender, profile);
  if (cov.status === "cubierto") { fin = 92; finNotes = ["con la combinación estimada alcanza a cubrirse"]; }
  else if (cov.status === "cerca") { fin = 72; finNotes = [`faltarían unos USD ${cov.gap.toLocaleString("en-US")} por año`]; }
  else if (cov.status === "falta") { fin = Math.max(5, 60 - cov.gap / 1000); finNotes = [`faltarían unos USD ${cov.gap.toLocaleString("en-US")} por año`]; }
  const financial = clamp(fin);

  const total = clamp(0.4 * athletic + 0.3 * academic + 0.3 * financial);
  return {
    total,
    parts: [
      { key: "athletic", label: "Deportivo", value: athletic, note: athleticNote },
      { key: "academic", label: "Académico", value: academic, note: `${careerNote}; ${gpaNote}; admisión ${adm.level}` },
      { key: "financial", label: "Financiero", value: financial, note: finNotes.join("; ") },
    ],
  };
}

function FitScoreBlock({ r, profile }) {
  const fs = useMemo(() => { try { return computeFitScore(r, profile); } catch (e) { return null; } }, [r, profile]);
  if (!fs) return null;
  const color = (v) => (v >= 70 ? "#1f7a3f" : v >= 45 ? "#8a5a00" : "#b3401a");
  return (
    <div className="rm-fitscore">
      <div className="rm-fitscore-head">
        <span>Fit Score</span>
        <b style={{ color: color(fs.total) }}>{fs.total}<small>/100</small></b>
      </div>
      {fs.parts.map((p) => (
        <div className="rm-fitscore-row" key={p.key}>
          <span className="rm-fitscore-label">{p.label}</span>
          <div className="rm-fitscore-bar"><div style={{ width: `${p.value}%`, background: color(p.value) }} /></div>
          <span className="rm-fitscore-val">{p.value}</span>
          <span className="rm-fitscore-note">{p.note}</span>
        </div>
      ))}
    </div>
  );
}

/* ---------------------------------------------------------------
   EMBUDO TIPO KANBAN + MÉTRICAS DE MAILS (Mi correo)
--------------------------------------------------------------- */
const KANBAN_COLUMNS = [
  { key: "por_contactar", label: "Por contactar", color: "#6b7a8f" },
  { key: "sin_respuesta", label: "Escrito, sin respuesta", color: "#2f6fb3" },
  { key: "respondio", label: "Respondió", color: "#1f7a3f" },
  { key: "visita", label: "Llamada o visita", color: "#6a3fb3" },
  { key: "oferta", label: "Oferta", color: "#b37a00" },
  { key: "rechazo", label: "Sin lugar", color: "#9a9a9a" },
];

function OutreachKanban({ log, favorites, onMove, onWrite }) {
  const [dragging, setDragging] = useState(null);
  const [dropTarget, setDropTarget] = useState(null);
  const inLog = new Set(Object.keys(log));
  const cards = [
    ...favorites.filter((u) => !inLog.has(u)).map((u) => ({ university: u, status: "por_contactar" })),
    ...Object.values(log),
  ];
  const byCol = Object.fromEntries(KANBAN_COLUMNS.map((c) => [c.key, cards.filter((x) => (x.status || "sin_respuesta") === c.key)]));
  const drop = (col) => {
    if (!dragging || col === "por_contactar") return;
    const card = cards.find((c) => c.university === dragging);
    if (card && card.status === "por_contactar") onWrite(dragging);
    else onMove(dragging, col);
    setDragging(null);
  };
  return (
    <div className="rm-kanban" role="list">
      {KANBAN_COLUMNS.map((c) => (
        <div key={c.key} className={`rm-kanban-col ${dropTarget === c.key ? "over" : ""}`} onDragOver={(ev) => { ev.preventDefault(); if (dropTarget !== c.key) setDropTarget(c.key); }} onDragLeave={() => setDropTarget((t) => (t === c.key ? null : t))} onDrop={() => { setDropTarget(null); drop(c.key); }}>
          <div className="rm-kanban-colhead" style={{ borderTopColor: c.color }}>{c.label} <span>{byCol[c.key].length}</span></div>
          {byCol[c.key].length === 0 && <div className="rm-kanban-empty">{c.key === "por_contactar" ? "Guardá universidades en Mi lista para verlas acá." : "—"}</div>}
          {byCol[c.key].map((x) => {
            const days = x.lastContact ? daysSince(x.lastContact) : null;
            const stale = followUpDue(x);
            return (
              <div key={x.university} className={`rm-kanban-card ${stale ? "stale" : ""}`} draggable onDragStart={() => setDragging(x.university)} onDragEnd={() => setDragging(null)}>
                <b>{x.university}</b>{x.status !== "por_contactar" && (() => { const h = coachHeat(x); return <span className="rm-fit-chip" style={{ background: h.bg, color: h.color, marginLeft: 6 }}>{h.label}</span>; })()}
                <div className="rm-kanban-meta">
                  {x.status === "por_contactar" ? "En tu lista" : `${x.timesContacted || 0} envío${x.timesContacted === 1 ? "" : "s"} · hace ${days === 0 ? "hoy" : `${days} d`}`}
                  {stale && <span className="rm-kanban-flag">SEGUIMIENTO</span>}
                </div>
                {x.status === "por_contactar" ? (
                  <button type="button" className="rm-btn-inline" onClick={() => onWrite(x.university)}>Escribir mail →</button>
                ) : (
                  <>
                    <div className="rm-kanban-move">
                      {(() => {
                        const movable = KANBAN_COLUMNS.filter((k) => k.key !== "por_contactar");
                        const i = movable.findIndex((k) => k.key === x.status);
                        return (
                          <>
                            <button type="button" className="rm-kanban-arrow" aria-label={`Pasar ${x.university} a la etapa anterior`} disabled={i <= 0} onClick={() => onMove(x.university, movable[i - 1].key)}>‹</button>
                            <span className="rm-kanban-stage">{movable[i] ? movable[i].label : ""}</span>
                            <button type="button" className="rm-kanban-arrow" aria-label={`Pasar ${x.university} a la etapa siguiente`} disabled={i < 0 || i >= movable.length - 1} onClick={() => onMove(x.university, movable[i + 1].key)}>›</button>
                          </>
                        );
                      })()}
                    </div>
                    <select aria-label={`Mover ${x.university}`} value={x.status} onChange={(ev) => onMove(x.university, ev.target.value)}>
                      {KANBAN_COLUMNS.filter((k) => k.key !== "por_contactar").map((k) => <option key={k.key} value={k.key}>{k.label}</option>)}
                    </select>
                  </>
                )}
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
}

function outreachDivision(university) {
  const p = PROGRAMS_ALL_SPORTS.find((x) => x.School === university);
  if (p && p.Division) return p.Division;
  const e = eadaFor(university);
  return e ? eadaDivision(e.cls) : "Sin dato";
}

function OutreachMetrics({ log }) {
  const entries = Object.values(log).filter((e) => e.firstContact);
  if (entries.length === 0) return null;
  const sent = entries.reduce((s, e) => s + (e.timesContacted || 0), 0);
  const replied = entries.filter((e) => OUTREACH_REPLY_STATUSES.includes(e.status));
  const positive = entries.filter((e) => ["respondio", "visita", "oferta"].includes(e.status));
  const withDates = replied.filter((e) => e.repliedAt);
  const avgDays = withDates.length ? withDates.reduce((s, e) => s + Math.max(0, (new Date(e.repliedAt) - new Date(e.firstContact)) / 86400000), 0) / withDates.length : null;
  const avgTouches = replied.length ? replied.reduce((s, e) => s + (e.timesContacted || 1), 0) / replied.length : null;
  const pending = entries.filter((e) => followUpDue(e)).length;
  const pct = (a, b) => (b ? `${Math.round((a / b) * 100)}%` : "—");

  const byDiv = {};
  entries.forEach((e) => {
    const d = outreachDivision(e.university);
    byDiv[d] = byDiv[d] || { contacted: 0, replied: 0 };
    byDiv[d].contacted++;
    if (OUTREACH_REPLY_STATUSES.includes(e.status)) byDiv[d].replied++;
  });

  // Respuesta según el gancho del primer mail y cantidad de envíos por tipo (solo envíos con detalle guardado).
  const byHook = {};
  const byKind = {};
  entries.forEach((e) => {
    const msgs = outreachMessages(e);
    msgs.forEach((m) => { if (!m.legacy) byKind[m.kind] = (byKind[m.kind] || 0) + 1; });
    const firstMsg = msgs[0];
    if (!firstMsg || firstMsg.legacy) return;
    const h = firstMsg.hook || "none";
    byHook[h] = byHook[h] || { contacted: 0, replied: 0 };
    byHook[h].contacted++;
    if (OUTREACH_REPLY_STATUSES.includes(e.status)) byHook[h].replied++;
  });

  const weeks = [];
  const now = new Date();
  for (let i = 7; i >= 0; i--) {
    const end = new Date(now.getTime() - i * 7 * 86400000);
    const start = new Date(end.getTime() - 7 * 86400000);
    let n = 0;
    entries.forEach((e) => (e.sentDates && e.sentDates.length ? e.sentDates : [e.lastContact]).forEach((d) => { const t = new Date(d); if (t > start && t <= end) n++; }));
    weeks.push(n);
  }
  const maxW = Math.max(1, ...weeks);

  return (
    <div className="rm-metrics">
      <div className="rm-metrics-grid">
        <div><span>Universidades contactadas</span><b>{entries.length}</b></div>
        <div><span>Mails enviados</span><b>{sent}</b></div>
        <div><span>Tasa de respuesta</span><b>{pct(replied.length, entries.length)}</b></div>
        <div><span>Respuestas positivas</span><b>{pct(positive.length, entries.length)}</b></div>
        <div><span>Días hasta la respuesta</span><b>{avgDays != null ? avgDays.toFixed(1).replace(".", ",") : "—"}</b></div>
        <div><span>Mails hasta que responden</span><b>{avgTouches != null ? avgTouches.toFixed(1).replace(".", ",") : "—"}</b></div>
        <div><span>Seguimientos pendientes</span><b style={{ color: pending ? "#b3401a" : undefined }}>{pending}</b></div>
      </div>
      <div className="rm-metrics-split">
        <div>
          <h4>Envíos por semana (últimas 8)</h4>
          <div className="rm-metrics-bars" aria-label="Envíos por semana">
            {weeks.map((n, i) => <div key={i} title={`${n} envío${n === 1 ? "" : "s"}`}><div style={{ height: `${(n / maxW) * 100}%` }} /><span>{n}</span></div>)}
          </div>
        </div>
        <div>
          <h4>Respuesta por división</h4>
          <div className="rm-exam-tablewrap"><table className="rm-exam-table">
            <thead><tr><th>División</th><th>Contactadas</th><th>Respondieron</th></tr></thead>
            <tbody>{Object.entries(byDiv).sort((a, b) => b[1].contacted - a[1].contacted).map(([d, v]) => <tr key={d}><td>{d}</td><td>{v.contacted}</td><td>{v.replied} ({pct(v.replied, v.contacted)})</td></tr>)}</tbody>
          </table></div>
        </div>
      </div>
      {Object.keys(byHook).length > 0 && (
        <div className="rm-metrics-split">
          <div>
            <h4>Respuesta según el gancho del primer mail</h4>
            <div className="rm-exam-tablewrap"><table className="rm-exam-table">
              <thead><tr><th>Gancho</th><th>Programas</th><th>Respondieron</th></tr></thead>
              <tbody>{Object.entries(byHook).sort((a, b) => b[1].contacted - a[1].contacted).map(([h, v]) => <tr key={h}><td>{HOOK_LABELS[h] || "Sin gancho"}</td><td>{v.contacted}</td><td>{v.replied} ({pct(v.replied, v.contacted)})</td></tr>)}</tbody>
            </table></div>
          </div>
          <div>
            <h4>Envíos por tipo de mail</h4>
            <div className="rm-exam-tablewrap"><table className="rm-exam-table">
              <thead><tr><th>Tipo</th><th>Envíos</th></tr></thead>
              <tbody>{Object.entries(byKind).sort((a, b) => b[1] - a[1]).map(([k, n]) => <tr key={k}><td>{(MAIL_KINDS[k] || {}).label || k}</td><td>{n}</td></tr>)}</tbody>
            </table></div>
          </div>
        </div>
      )}
      <p className="rm-exam-note">
        Las aperturas no se pueden medir: el mail sale desde tu propia cuenta, así que el sitio no ve si el coach lo abrió. Las respuestas se cuentan cuando movés la tarjeta en el tablero.
        Las fechas de respuesta se registran desde esta versión: los envíos anteriores cuentan en la tasa, pero no en los días hasta la respuesta.
      </p>
    </div>
  );
}

/* ---------------------------------------------------------------
   CHECKLIST CRONOLÓGICO POR AÑO DE INGRESO + READINESS SCORE
   Las etapas se calculan hacia atrás desde agosto del año en que empezás a jugar en EE.UU.
--------------------------------------------------------------- */
function monthsToEntry(profile) {
  const entry = new Date(getEntryYear(profile), 7, 1);
  const now = new Date();
  return (entry.getFullYear() - now.getFullYear()) * 12 + (entry.getMonth() - now.getMonth());
}
function buildYearChecklist(profile) {
  const log = Object.values(readOutreachLog());
  const contacted = log.length;
  const replied = log.filter((e) => OUTREACH_REPLY_STATUSES.includes(e.status)).length;
  const offers = log.filter((e) => e.status === "oferta").length;
  const favs = readFavorites().length;
  const elig = readJSON("rr_eligibility_checklist", {});
  const eligDone = Object.values(elig).filter(Boolean).length;
  const examBest = readJSON("rr_exam_best", {});
  const practiced = Object.keys(examBest || {}).length > 0;
  const p = profile || {};
  const statsLoaded = (Number(p.goals) || 0) + (Number(p.assists) || 0) > 0;
  const entry = profile ? getEntryYear(profile) : null;
  return [
    { from: 36, title: "Armá tu base", items: [
      { id: "y-profile", label: "Perfil completo: deporte, posición, año de egreso y carrera", auto: !!(p.name && p.sport && p.position && p.major), goto: "form" },
      { id: "y-gpa", label: "Promedio convertido a escala 4.0", auto: typeof p.gpa4 === "number" && p.gpa4 > 0, goto: "gpa" },
      { id: "y-divisions", label: "Entendés qué divisiones dan becas y cuál es realista para vos", goto: "resources" },
    ] },
    { from: 30, title: "Elegibilidad y primeros datos", items: [
      { id: "y-elig", label: "Empezaste la checklist de materias troncales", auto: eligDone > 0, goto: "eligibility" },
      { id: "y-ec", label: "Te registraste en el NCAA Eligibility Center (D1/D2; D3 con cuenta Amateurism-Only) o en el de la NAIA", link: "https://web3.ncaa.org/ecwr3" },
      { id: "y-stats", label: "Cargaste tus estadísticas de la temporada", auto: statsLoaded, goto: "form" },
    ] },
    { from: 28, title: "Video y lista de universidades", items: [
      { id: "y-video", label: "Video de highlights cargado en tu perfil", auto: !!p.videoLink, goto: "form" },
      { id: "y-list", label: `Lista de 30 a 50 programas guardada (${favs} en Mi lista)`, auto: favs >= 30, goto: "catalog" },
      { id: "y-english-diag", label: "Rendiste un examen de inglés de diagnóstico" },
    ] },
    { from: 24, title: "Primer contacto con coaches", items: [
      { id: "y-first10", label: `Primer mail a al menos 10 coaches (${contacted} contactados)`, auto: contacted >= 10, goto: "outreach" },
      { id: "y-ncaaid", label: "Le diste tu NCAA ID a cada coach: sin eso la universidad no puede iniciar tu caso en el Eligibility Center" },
      { id: "y-exampractice", label: "Practicaste en la sección Exámenes", auto: practiced, goto: "exams" },
      { id: "y-camps", label: "Averiguaste camps o torneos donde vayan los coaches de tu lista" },
    ] },
    { from: 12, title: "Seguimiento y examen definitivo", items: [
      { id: "y-30", label: `Mail a 30 coaches o más (${contacted} contactados)`, auto: contacted >= 30, goto: "outreach" },
      { id: "y-reply", label: `Al menos un coach te respondió (${replied} respuestas)`, auto: replied > 0, goto: "outreach" },
      { id: "y-english", label: "Rendiste el examen de inglés que pide la universidad (confirmá con ellos qué test y qué vigencia aceptan)" },
      { id: "y-sat", label: "SAT o ACT, solo si tus universidades lo piden o buscás becas por mérito" },
    ] },
    { from: 8, title: "Ofertas y decisión", items: [
      { id: "y-offer", label: `Recibiste al menos una oferta (${offers} en el tablero)`, auto: offers > 0, goto: "outreach" },
      { id: "y-compare", label: "Comparaste cada oferta contra el costo real antes de responder" },
      { id: "y-amateur", label: "Pediste la certificación final de amateurismo en tu cuenta del Eligibility Center (D1, D2 y D3)" },
    ] },
    { from: 5, title: `Firma, visa y viaje${entry ? ` (agosto de ${entry})` : ""}`, items: [
      { id: "y-sign", label: "Firmaste el acuerdo de beca por escrito" },
      { id: "y-i20", label: "Recibiste el formulario I-20 de la universidad y pagaste el SEVIS" },
      { id: "y-visa", label: "Sacaste turno y tuviste la entrevista de visa F-1" },
    ] },
  ];
}
function computeReadiness(profile, checklist, manual) {
  const m = profile ? monthsToEntry(profile) : 36;
  const isDone = (it) => (it.auto !== undefined ? it.auto : !!manual[it.id]);
  const due = checklist.filter((st) => m <= st.from).flatMap((st) => st.items);
  const all = checklist.flatMap((st) => st.items);
  const doneDue = due.filter(isDone).length;
  const doneAll = all.filter(isDone).length;
  const p = profile || {};
  const profileFields = [p.name, p.email, p.sport, p.position, p.major, p.videoLink, typeof p.gpa4 === "number" && p.gpa4 > 0].filter(Boolean).length;
  const profilePart = (profileFields / 7) * 25;
  const duePart = due.length ? (doneDue / due.length) * 60 : 60;
  const aheadPart = (doneAll / all.length) * 15;
  const score = Math.max(0, Math.min(100, Math.round(profilePart + duePart + aheadPart)));
  const overdue = due.filter((it) => !isDone(it));
  const label = score >= 75 ? "Al día" : score >= 50 ? "En camino" : "Atrasado";
  const color = score >= 75 ? "#1f7a3f" : score >= 50 ? "#8a5a00" : "#b3401a";
  const parts = [
    { key: "Al día", value: Math.round(duePart), max: 60, hint: due.length ? `${doneDue} de ${due.length} tareas que ya te tocan` : "Nada que te toque todavía" },
    { key: "Perfil", value: Math.round(profilePart), max: 25, hint: `${profileFields} de 7 datos cargados` },
    { key: "Adelantado", value: Math.round(aheadPart), max: 15, hint: `${doneAll} de ${all.length} tareas del camino` },
  ];
  return { score, label, color, monthsLeft: m, overdue, doneAll, total: all.length, isDone, parts };
}

function YearChecklist({ profile, setStage }) {
  const [manual, toggleManual] = useRoadmapManual();
  const checklist = buildYearChecklist(profile);
  const rd = computeReadiness(profile, checklist, manual);
  const m = rd.monthsLeft;
  return (
    <div>
      <div className="rm-readiness" style={{ borderColor: rd.color }}>
        <div>
          <span className="rm-readiness-kicker">Readiness Score</span>
          <b style={{ color: rd.color }}>{rd.score}<small>/100</small></b>
          <span className="rm-fit-chip" style={{ background: rd.color + "1a", color: rd.color }}>{rd.label}</span>
        </div>
        <p>
          {profile
            ? m > 0 ? `Faltan ${m} meses para tu ingreso (agosto de ${getEntryYear(profile)}).` : `Tu ingreso es en agosto de ${getEntryYear(profile)}.`
            : "Cargá tu perfil para calcular las etapas según tu año de ingreso."}
          {" "}Mide qué tan al día estás con lo que ya te toca hacer (60%), qué tan completo está tu perfil (25%) y cuánto adelantaste de lo que viene (15%).
          {rd.overdue.length > 0 && <><br /><b>Lo que ya te toca y falta:</b> {rd.overdue.slice(0, 4).map((x) => x.label.replace(/ \(.*\)$/, "")).join(" · ")}{rd.overdue.length > 4 ? ` y ${rd.overdue.length - 4} más` : ""}.</>}
        </p>
      </div>
      <div style={{ display: "grid", gap: 10, margin: "12px 0 4px" }}>
        {rd.parts.map((pt) => (
          <div key={pt.key} style={{ display: "grid", gridTemplateColumns: "110px 1fr 52px", gap: 10, alignItems: "center", fontSize: 13 }}>
            <span style={{ fontWeight: 700 }}>{pt.key}</span>
            <div>
              <div style={{ height: 8, background: "var(--paper-dim)", borderRadius: 4, overflow: "hidden" }}>
                <div style={{ width: `${(pt.value / pt.max) * 100}%`, height: "100%", background: rd.color, transition: "width .3s" }} />
              </div>
              <small style={{ color: "var(--ink-soft)" }}>{pt.hint}</small>
            </div>
            <span style={{ textAlign: "right", fontWeight: 700 }}>{pt.value}/{pt.max}</span>
          </div>
        ))}
      </div>
      {checklist.map((st) => {
        const state = m > st.from ? "futuro" : "actual";
        const done = st.items.filter(rd.isDone).length;
        return (
          <div key={st.title} style={{ marginTop: 26, opacity: state === "futuro" ? 0.72 : 1 }}>
            <h3 className="rm-condensed" style={{ fontSize: 17 }}>
              {st.title} <span style={{ fontSize: 12, color: "var(--ink-soft)", fontWeight: 400 }}>
                · {st.from} meses antes de tu ingreso{profile ? ` (${MONTHS_ES[new Date(getEntryYear(profile), 7 - st.from, 1).getMonth()]} de ${new Date(getEntryYear(profile), 7 - st.from, 1).getFullYear()})` : ""} · {done}/{st.items.length}{state === "futuro" ? " · todavía no te toca" : ""}
              </span>
            </h3>
            <div className="rm-elig-list">
              {st.items.map((item) => {
                const isDoneItem = rd.isDone(item);
                const auto = item.auto !== undefined;
                return (
                  <div className="rm-elig-item" key={item.id} style={{ cursor: auto ? "default" : "pointer" }} onClick={() => { if (!auto) toggleManual(item.id); }}>
                    <input type="checkbox" checked={isDoneItem} disabled={auto} onChange={() => { if (!auto) toggleManual(item.id); }} aria-label={item.label} />
                    <div style={{ flex: 1 }}>
                      <div className="rm-elig-item-title">{item.label}{auto && <span style={{ fontSize: 11, color: "var(--ink-soft)", marginLeft: 6 }}>(se marca solo)</span>}</div>
                      {item.goto && <button className="rm-btn-inline" onClick={(e) => { e.stopPropagation(); setStage(item.goto); }}>Ir →</button>}
                      {item.link && <a className="rm-btn-inline" href={item.link} target="_blank" rel="noreferrer" onClick={(e) => e.stopPropagation()}>Abrir sitio oficial →</a>}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function RoadmapPage({ profile, setStage, embedded }) {
  return (
    <div className={embedded ? "" : "rm-wrap"} style={embedded ? {} : { paddingTop: 40, paddingBottom: 60 }}>
      <h2 className="rm-condensed">Hoja de ruta</h2>
      <p className="rm-hint">
        Tu checklist en orden cronológico, calculado hacia atrás desde agosto del año en que empezás a jugar en EE.UU. Los pasos que el sitio puede comprobar se marcan solos; el resto lo tildás vos.
      </p>
      {!profile && <div className="rm-alert" style={{ marginTop: 14 }}><b>Todavía no cargaste tu perfil.</b> Sin tu año de egreso, las etapas no se pueden ubicar en el tiempo. <button className="rm-btn-inline" onClick={() => setStage("form")}>Armar mi perfil →</button></div>}
      <YearChecklist profile={profile} setStage={setStage} />
      <p style={{ fontSize: 11.5, color: "var(--ink-soft)", marginTop: 24 }}>Lo que tildás a mano se guarda en tu navegador y, si iniciaste sesión, en tu cuenta.</p>
    </div>
  );
}

// Guía completa para atletas internacionales — la mayoría de quienes usan Smartrecruit
// no son ciudadanos de EEUU y nunca navegaron esta burocracia. El objetivo es que
// entiendan cada fase con sus propias palabras, sin pagarle a una agencia ni ir a un
// showcase, no que tilden una lista de tareas sin entender el porqué.
// Fuente: ncsasports.org/recruiting/how-to-get-recruited/international-athletes,
// consultado el 14/9/2026.
function InternationalAthletesSection() {
  return (
    <div className="rm-sp-section" style={{ marginTop: 26, border: "2px solid var(--navy)", borderRadius: 6, padding: "24px 22px" }}>
      <h3 className="rm-condensed" style={{ fontSize: 20, marginTop: 0 }}>Guía para atletas internacionales</h3>
      <p style={{ fontSize: 13.5, color: "var(--ink-soft)" }}>
        Esto te aplica a vos casi seguro. Adaptado de <a href="https://www.ncsasports.org/recruiting/how-to-get-recruited/international-athletes" target="_blank" rel="noreferrer">NCSA — International Student Athletes</a>, consultado 14/9/2026.
      </p>
      <p style={{ fontSize: 14.5, lineHeight: 1.6, marginTop: 10 }}>
        Todos los años, miles de atletas que no son de EEUU consiguen jugar su deporte ahí mientras estudian gratis o casi gratis — hoy hay más de 25.000 atletas internacionales compitiendo en la NCAA. Es una oportunidad real. El proceso tiene sus reglas y su papelerío, pero no hace falta pagarle a una agencia ni viajar a un showcase para entenderlo: acá te lo explicamos paso a paso, en criollo.
      </p>

      <h4 className="rm-condensed" style={{ fontSize: 16, marginTop: 22 }}>¿Qué deportes reclutan más internacionales?</h4>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>
        Algunos deportes están más acostumbrados a reclutar afuera de EEUU que otros: <b>tenis, hockey sobre hielo, golf, field hockey, soccer, natación y water polo</b>. Los coaches de esos deportes ya saben cómo evaluar a alguien que nunca vieron jugar en persona, y muchos ya tramitaron visas antes. <b>Field Hockey y Soccer —los que más cargamos en Smartrecruit— están en esa lista.</b> Deportes como fútbol americano, béisbol, softbol, lacrosse, vóley o wrestling reclutan menos internacionales — no es que sea imposible, pero vas a tener que esforzarte más para que te vean.
      </p>

      <h4 className="rm-condensed" style={{ fontSize: 16, marginTop: 22 }}>¿Cuándo hay que arrancar?</h4>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>
        Cuanto antes, mejor — nunca es demasiado temprano. Arrancar temprano te da tiempo para investigar universidades, entender qué te exige cada una y empezar a construir una relación con los coaches antes de que la competencia se pisotee toda escribiéndoles el mismo mes. El error más común es quedarse esperando a que un coach te escriba primero. Las reglas de reclutamiento de la NCAA limitan bastante cuándo un coach puede contactarte a vos — pero no hay ninguna regla que te impida escribirle vos primero. Mandá el email, mandá el video, sé el que da el primer paso.
      </p>

      <h4 className="rm-condensed" style={{ fontSize: 16, marginTop: 22 }}>¿Qué tengo que saber antes de arrancar?</h4>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>
        Vas a tener que investigar bastante, y al principio va a sonar todo en un idioma raro (literal y figurado). Algunas cosas que ayudan:
      </p>
      <ul style={{ fontSize: 14, lineHeight: 1.7, paddingLeft: 20 }}>
        <li><b>Aprendé la jerga.</b> Vas a escuchar mucho "grad year" — es simplemente el año en que terminás el secundario y arrancarías la universidad. No es nada más complicado que eso.</li>
        <li><b>Entendé que hay tres ligas distintas</b> (NCAA, NAIA, NJCAA), con sus propios plazos y su propia idea de qué buscan en un recluta internacional. No es una sola "NCAA" que decide todo.</li>
        <li><b>Entendé los requisitos de elegibilidad</b> — te vas a tener que registrar en el Eligibility Center de la NCAA o de la NAIA, y vas a necesitar mandar (y a veces traducir) documentos oficiales que prueben tus notas, tus exámenes y tus materias. Lo vemos en detalle más abajo.</li>
        <li><b>Armá tu lista de universidades con la cabeza fría.</b> No es solo "¿me aceptan?" — es también "¿me banco el clima de esa zona? ¿prefiero ciudad grande o pueblo chico? ¿cuántos estudiantes tiene?". Ya tenés esos datos cargados en cada perfil de universidad de Smartrecruit.</li>
      </ul>

      <h4 className="rm-condensed" style={{ fontSize: 16, marginTop: 22 }}>¿Por qué el video es tan importante para mí en particular?</h4>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>
        Para vos, el video no es "un plus" — es prácticamente la única forma que un coach de EEUU tiene de evaluarte, porque es muy poco probable que viaje a verte jugar en persona. Hay dos tipos:
      </p>
      <ul style={{ fontSize: 14, lineHeight: 1.7, paddingLeft: 20 }}>
        <li><b>Video de highlights.</b> Clips cortos de tus mejores jugadas en partidos reales — mostrá tu técnica, tu lectura del juego, tu atletismo.</li>
        <li><b>Video de habilidades (skills).</b> Ejercicios/drills fuera de partido, para que el coach vea de cerca tu técnica en movimientos específicos.</li>
      </ul>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>Lo importante es que sea claro, ordenado y fácil de mirar — no hace falta producción profesional, hace falta que se entienda rápido quién sos jugando. Un dato concreto: <b>no lo hagas más largo de 5 minutos</b> — salvo que ya estén realmente interesados en vos, la mayoría de los coaches no se toman el tiempo de mirar un video más largo que eso. Acompañá el video de partido con una ficha corta (posición, número de camiseta, altura/peso, tus mejores stats) para que el coach sepa exactamente a quién está mirando en la pantalla.</p>
      <p style={{ fontSize: 13.5, lineHeight: 1.6, color: "var(--ink-soft)" }}>Pedile a tu entrenador si el club tiene equipo de filmación o edición — muchos ya grababan los partidos igual. Si no, cualquier compañía chica de edición de video local puede armarte el corte.</p>

      <h4 className="rm-condensed" style={{ fontSize: 16, marginTop: 22 }}>¿Cómo contacto a un coach?</h4>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>
        No esperes a que te vean — contactalos vos primero:
      </p>
      <ul style={{ fontSize: 14, lineHeight: 1.7, paddingLeft: 20 }}>
        <li><b>Email:</b> corto y personalizado, con tu info académica y deportiva, más el link a tu perfil y tu video. Es la mejor forma de presentarte y de proponer una llamada.</li>
        <li><b>Llamada, mensaje o videollamada:</b> una vez que ya hubo contacto, seguir por Zoom/FaceTime/Skype ayuda a construir la relación. Muchos coaches ya están acostumbrados a esto con reclutas internacionales.</li>
        <li><b>Redes sociales:</b> algunos coaches (o su staff) están activos en Instagram o X — si les escribís por ahí, mantenelo profesional y al punto.</li>
      </ul>
      <p style={{ fontSize: 13.5, lineHeight: 1.6, fontStyle: "italic", color: "var(--ink-soft)" }}>Ojo con los husos horarios: un email a la madrugada lo van a entender; una llamada mientras están durmiendo, no tanto.</p>

      <h4 className="rm-condensed" style={{ fontSize: 16, marginTop: 22 }}>¿Puedo conseguir beca o ayuda financiera siendo internacional?</h4>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>
        Sí, y esto es lo que más se malentiende. Podés calificar para varios tipos de ayuda:
      </p>
      <ul style={{ fontSize: 14, lineHeight: 1.7, paddingLeft: 20 }}>
        <li><b>Becas deportivas</b> — completas o parciales, en D1, D2, NAIA y NJCAA. Ojo: la mayoría cubre solo una parte de matrícula/alojamiento/comida, no el 100%.</li>
        <li><b>Becas académicas</b> — por buen GPA, buen puntaje de examen o buen ranking de tu clase.</li>
        <li><b>Becas no-académicas</b> — por actividades extracurriculares, liderazgo, voluntariado, aunque tu GPA no sea el más alto.</li>
        <li><b>Ayuda institucional propia de cada universidad</b> — muchas universidades tienen su propio fondo de ayuda, separado del gobierno, y sí se lo dan a internacionales según necesidad.</li>
      </ul>
      <div className="rm-alert" style={{ marginTop: 12 }}>
        <b>Lo que NO existe para vos como internacional:</b> ayuda federal de EEUU (FAFSA, grants, Federal Work Study) ni préstamos federales — esos son solo para ciudadanos/residentes. Sí podés acceder a préstamos privados, pero casi siempre te van a pedir un cosigner (alguien que sea ciudadano o residente de EEUU con buen crédito) — y a diferencia de una beca, un préstamo hay que devolverlo, con intereses. El rango de "ayuda estimada" que ves en tu Recruit Score sale del costo real y las becas institucionales de cada universidad (Common Data Set) — no de ayuda federal, que nunca vas a poder usar.
      </div>

      <h4 className="rm-condensed" style={{ fontSize: 16, marginTop: 22 }}>Requisitos académicos de la NCAA para internacionales</h4>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>
        El NCAA Eligibility Center no te ayuda a cumplir los requisitos — solo los verifica. Es tu responsabilidad registrarte y llevar la cuenta vos mismo. Como internacional, vas a tener que mandar:
      </p>
      <ul style={{ fontSize: 14, lineHeight: 1.7, paddingLeft: 20 }}>
        <li><b>Tus notas/boletines</b> desde 9no grado (3er año en una secundaria de 6 años, 2° si es de 5) en adelante, en tu idioma — y traducidas al inglés si no es inglés.</li>
        <li><b>Prueba de que te graduaste</b> — el título en sí, un certificado, o una copia de tus exámenes finales.</li>
      </ul>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>Y tenés que cumplir lo mismo que cualquier otro postulante:</p>
      <ul style={{ fontSize: 14, lineHeight: 1.7, paddingLeft: 20 }}>
        <li><b>16 materias "core" aprobadas por la NCAA</b> (inglés, matemática, ciencia, ciencias sociales, idioma extranjero o filosofía/religión comparada) — la cantidad exacta de cada tipo varía entre D1 y D2 (lo vas a ver más abajo cuando elijas tu división).</li>
        <li><b>GPA mínimo en esas materias:</b> 2.3 para D1, 2.2 para D2.</li>
        <li><b>Aprobar las reglas de amateurismo</b> — te van a preguntar sobre tu historial deportivo y educativo para confirmar que calificás como amateur.</li>
      </ul>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>La buena noticia: <b>el SAT/ACT ya no es obligatorio</b> para la elegibilidad deportiva de la NCAA (se sacó en 2023). Pero cuidado — la universidad en sí, para la admisión académica (que es un trámite distinto), todavía puede pedirlo. Confirmá con cada universidad puntual.</p>

      <div className="rm-argentina-box">
        <h4 className="rm-condensed" style={{ fontSize: 15.5, marginTop: 0 }}>🇦🇷 Si estudiaste en Argentina (de la guía oficial de la NCAA, edición 2025-26)</h4>
        <p style={{ fontSize: 13.5, lineHeight: 1.6 }}>La NCAA tiene una ficha propia por país. Esto es exactamente lo que dice la de Argentina:</p>
        <p style={{ fontSize: 13.5, lineHeight: 1.6 }}><b>Certificados que SÍ te sirven como prueba de graduación:</b> Título de Bachiller · Bachillerato Especializado · Certificado de Técnico · Perito Mercantil · Certificado de Educación Polimodal.</p>
        <p style={{ fontSize: 13.5, lineHeight: 1.6 }}><b>Lo que NO te sirve como prueba de graduación:</b> solo haber completado el Ciclo Básico, solo haber completado 7° año, o el Título de Técnico Superior en Comercio Exterior por sí solo.</p>
        <p style={{ fontSize: 13.5, lineHeight: 1.6 }}><b>Qué documentos vas a tener que mandar:</b> tus boletines desde 9° grado de EE.UU. en adelante (3er año en una secundaria de 6 años, 2° si es de 5) — en español, más la traducción certificada al inglés. La NCAA puede pedirte además el boletín de 8° año, el certificado/título en sí, y las escalas de calificación de cada colegio.</p>
        <p style={{ fontSize: 13.5, lineHeight: 1.6, fontWeight: 700, marginTop: 10 }}>El dato que más te conviene saber: cómo te convierten la nota.</p>
        <p style={{ fontSize: 13.5, lineHeight: 1.6 }}>
          La NCAA usa por default la escala <b>"Six Minimum-Pass"</b> para convertir tu promedio argentino (escala 1-10) a la escala de EEUU (4.0) — <b>no es una regla de tres simple</b>, es escalonada:
        </p>
        <table className="rm-arg-grade-table">
          <thead><tr><th>Tu nota (1-10)</th><th>Equivalente EEUU</th><th>Puntos</th></tr></thead>
          <tbody>
            <tr><td>10</td><td>A</td><td>4.0</td></tr>
            <tr><td>8 – 9.99</td><td>A</td><td>4.0</td></tr>
            <tr><td>7 – 7.99</td><td>B</td><td>3.0</td></tr>
            <tr><td>6 – 6.99</td><td>C</td><td>2.0</td></tr>
            <tr><td>Menos de 6</td><td>F</td><td>0.0</td></tr>
          </tbody>
        </table>
        <p style={{ fontSize: 13, lineHeight: 1.6, color: "var(--ink-soft)", marginTop: 8 }}>
          Ya actualizamos el Conversor de GPA de Smartrecruit para usar exactamente esta tabla. Ojo con un detalle: si tu colegio usaba la escala alternativa "Four Minimum-Pass" (menos común), la NCAA <i>de todas formas</i> asume la de arriba salvo que tu colegio aclare por escrito en el boletín (o en una carta con membrete) cuál usó — así que convendría chequear esto con tu colegio antes de mandar la documentación.
        </p>
        <p style={{ fontSize: 13, lineHeight: 1.6, marginTop: 10 }}>
          <b>Reglas de traducción (aplican para cualquier país, no solo Argentina):</b> tiene que ser una traducción literal, palabra por palabra, hecha por alguien <i>que no sea pariente tuyo ni del club/colegio que te recluta</i> — puede ser un profesor de inglés de universidad o un traductor certificado. Esa persona tiene que adjuntar una carta con su nombre completo, contacto, y por qué está calificada para traducir. Sin eso, la NCAA rechaza la traducción.
        </p>
      </div>

      <h4 className="rm-condensed" style={{ fontSize: 16, marginTop: 22 }}>Requisitos académicos de la NAIA para internacionales</h4>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>
        Si tu secundario fue fuera de EEUU (aunque seas ciudadano de EEUU), la NAIA te pide un <b>promedio general de 2.3 o más</b> (escala 4.0) <b>o</b> cumplir <b>2 de estos 3</b> requisitos:
      </p>
      <ul style={{ fontSize: 14, lineHeight: 1.7, paddingLeft: 20 }}>
        <li><b>Examen estandarizado:</b> ACT 18+ o SAT 970+ (solo lectura/escritura basada en evidencia + matemática, no cuenta el score de Writing), rendido en una fecha internacional, enviado directo a la NAIA con el código <b>9876</b>.</li>
        <li><b>Ranking de tu clase:</b> graduarte en el 50% superior de tu curso, con una carta del colegio en papel membretado que indique tu posición y el total de alumnos.</li>
        <li><b>GPA general:</b> 2.0 o más en escala 4.0.</li>
      </ul>
      <p style={{ fontSize: 14, lineHeight: 1.6 }}>
        Un paso extra que solo te toca a vos por ser internacional: la NAIA exige que compres y completes una evaluación de <a href="https://www.incredevals.org/" target="_blank" rel="noreferrer">InCred</a> — tu secundario tiene que mandar tus notas directo a ellos, y solo lo que InCred verifica cuenta para tu elegibilidad. Es un trámite pago, pero mucho más barato y simple que contratar una agencia de reclutamiento.
      </p>
      <ul style={{ fontSize: 14, lineHeight: 1.7, paddingLeft: 20 }}>
        <li><b>Costo:</b> USD $170 (desde el 15/9/2025), único pago, no reembolsable — es la tarifa de registro internacional (los graduados de escuelas militares de EEUU pagan la tarifa doméstica, más baja). Se paga con Visa, MasterCard, Discover, o giro postal. No hay becas ni exenciones de esta tarifa para internacionales.</li>
        <li><b>Cuándo registrarte:</b> apenas te gradúes, o al terminar el ciclo lectivo. Si vas a entrar en el semestre de otoño (agosto/septiembre), mandá todo al menos 2 meses antes — no esperés a las vacaciones de verano de EEUU (junio-agosto), ahí muchas oficinas están cerradas y se demora todo.</li>
        <li><b>Cuánto tarda:</b> una vez que está todo completo (perfil online + coach te puso en su "Short List" + InCred verificó tus notas + llegó tu examen), la revisión tarda unos 20 días hábiles.</li>
        <li><b>Traducciones:</b> las notas van en el idioma original y con una traducción literal al inglés, palabra por palabra. No hace falta que esté certificada ni sellada.</li>
        <li><b>Ojo con esto:</b> podés aceptar la beca y firmar con la universidad antes de tener la determinación final de elegibilidad — pero no podés competir en la NAIA hasta que te la den.</li>
      </ul>

      <p style={{ fontSize: 13, color: "var(--ink-soft)", marginTop: 18, fontStyle: "italic" }}>
        Nada de esto reemplaza el trámite oficial — la certificación real la hace el NCAA/NAIA Eligibility Center. Pero ya sabés, en tu idioma, qué te va a pedir cada uno y por qué.
      </p>
    </div>
  );
}

// Términos y límites sacados directo de la guía de reclutamiento de la NCAA.
const RECRUITING_GLOSSARY = [
  { term: "Contacto (Contact)", def: "Cualquier momento en que un coach te habla en persona a vos o a tus padres fuera del campus de la universidad, más que un simple \"hola\" — también cuenta si pasa en tu colegio o donde entrenás/competís." },
  { term: "Período de contacto", def: "El coach puede tener contacto en persona con vos y tus padres, dentro o fuera del campus. Puede verte jugar, visitar tu colegio, y escribirte/llamarte." },
  { term: "Período muerto (Dead period)", def: "El coach NO puede tener ningún contacto en persona con vos ni tus padres, ni dentro ni fuera del campus. Sí puede escribirte o llamarte por teléfono. Solo aplica a D1 y D2; D3 no tiene periodos muertos." },
  { term: "Período de evaluación", def: "El coach puede verte jugar o visitar tu colegio, pero no puede tener conversaciones en persona con vos fuera del campus. Vos y tus padres sí pueden visitar el campus. El coach puede escribirte o llamarte." },
  { term: "Período silencioso (Quiet period)", def: "El coach no puede tener contacto en persona con vos ni tus padres fuera del campus, ni verte jugar, ni visitar tu colegio. Vos sí podés visitar el campus. El coach puede escribirte o llamarte. Solo aplica a D1 y D2; D3 y NAIA no lo tienen." },
  { term: "Visita oficial", def: "Visita al campus pagada (total o parcial) por la universidad: puede cubrir tu viaje, alojamiento, hasta 3 comidas por día y hasta 3 entradas a un evento deportivo. En D1 podés hacer una visita oficial por escuela (salvo que cambie el head coach). No puede caer en un período muerto. Antes de invitarte, la universidad necesita saber que sos elegible: en D1 y D2, tenés que estar registrado en el Eligibility Center." },
  { term: "Visita no oficial", def: "Visita al campus que pagás vos. Podés hacer todas las que quieras, en cualquier momento del año. En D1, hasta el 1 de agosto de tu año junior no podés coordinar la visita con el coach ni hablar de reclutamiento con él. En D2, D3 y NAIA podés hacerlo siempre. Durante un período muerto, el coach no puede hablar con vos en persona." },
  { term: "Atleta prospecto (Prospective student-athlete)", def: "Empezás a ser considerado \"prospecto\" desde que arrancás 9° grado — o antes, si la universidad ya te da a vos, a tu familia o amigos algún beneficio que no le da a cualquier estudiante." },
  { term: "Compromiso verbal", def: "Cuando anunciás que vas a ir a una universidad antes de firmar (o poder firmar) el acuerdo de ayuda atlética. No es un compromiso legal para ninguna de las dos partes — solo la firma del acuerdo de ayuda atlética es vinculante." },
  { term: "Acuerdo de ayuda atlética (antes, Carta de Intención o NLI)", def: "Documento por el que la universidad te da ayuda financiera (incluida la beca deportiva) y vos te comprometés a inscribirte. En NCAA División I reemplazó a la Carta de Intención Nacional (NLI) desde 2024; en otras divisiones y en NJCAA puede tener otro nombre. Una vez firmado, es vinculante." },
];

