function AppInner() {
  const [stage, setStageRaw] = useState(stageFromPath);
  // Cambiar de sección agrega una entrada al historial, así el botón "atrás" del navegador funciona.
  const setStage = (next) => {
    setStageRaw(next);
    try {
      if (PATH_STAGES.includes(next) && next !== "school") {
        const target = `/${next}`;
        if (window.location.pathname !== target) window.history.pushState({ stage: next }, "", target);
      } else if (next === "landing" && window.location.pathname !== "/") {
        window.history.pushState({ stage: next }, "", "/");
      }
    } catch (e) {}
  };
  useEffect(() => {
    const onPop = () => setStageRaw(stageFromPath());
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);
  const [dataVersion, setDataVersion] = useState(0);
  const [dataAsOf, setDataAsOf] = useState(null);
  useEffect(() => {
    if (typeof fetch !== "function") return undefined; // navegadores sin fetch: se usan los datos embebidos
    let cancelled = false;
    try {
      fetch("/data/live.json", { cache: "no-cache" })
        .then((r) => (r.ok ? r.json() : null))
        .then((live) => { if (!cancelled && applyLiveData(live)) { setDataAsOf(live.generatedAt || null); setDataVersion((v) => v + 1); } })
        .catch(() => {});
    } catch (e) { /* sin datos vivos: se usan los embebidos */ }
    return () => { cancelled = true; };
  }, []);
  const [profile, setProfile] = useState(() => {
    try { const p = JSON.parse(localStorage.getItem("rr_profile") || "null"); return p; } catch (e) { return null; }
  });
  const saveProfile = (p) => {
    const normalized = normalizeProfile(p);
    setProfile(normalized);
    writeJSON("rr_profile", normalized);
  };
  usePlanReminder();
  const [selectedSchool, setSelectedSchool] = useState(null);
  const [outreachPick, setOutreachPick] = useState(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const openSchool = (name) => { setSelectedSchool(name); setStage("school"); window.scrollTo(0, 0); };

  // ---- Sesión (Supabase): magic link por email, con migración automática del progreso guardado en este navegador ----
  const [session, setSession] = useState(null);
  useEffect(() => {
    let mounted = true;
    supabase.auth.getSession().then(({ data }) => { if (mounted) setSession(data.session); });
    const { data: sub } = supabase.auth.onAuthStateChange(async (event, sess) => {
      if (!mounted) return;
      setSession(sess);
      syncUserId = sess ? sess.user.id : null;
      // Si quedó algo sin subir (por ejemplo, se editó sin conexión), se reintenta apenas hay sesión.
      if (sess) { try { if (localStorage.getItem("rr_sync_pending")) scheduleSync(); } catch (e) { /* nada */ } }
      // Supabase también dispara SIGNED_IN al recargar la página con una sesión ya guardada.
      // Sin este chequeo, cada recarga dispara otra recarga (bucle). Solo se procesa un login por cuenta en este navegador.
      let handled = null;
      try { handled = localStorage.getItem("rr_login_handled_uid"); } catch (e) {}
      if (event === "SIGNED_OUT") { try { localStorage.removeItem("rr_login_handled_uid"); } catch (e) {} }
      if (event === "PASSWORD_RECOVERY") { try { localStorage.setItem("rr_need_new_password", "1"); } catch (e) {} }
      if (event === "SIGNED_IN" && sess && handled !== sess.user.id) {
        try { localStorage.setItem("rr_login_handled_uid", sess.user.id); } catch (e) {}
        await syncOnLogin(sess.user.id); // combina la nube con lo de este navegador (lo más nuevo gana, clave por clave) y sube el resultado
        window.location.reload(); // recarga simple: todo el sitio lee su estado inicial de localStorage, así queda consistente en un solo lugar
      }
    });
    return () => { mounted = false; sub.subscription.unsubscribe(); };
  }, []);


  const NAV_LINKS = [
    { id: "landing", label: "Inicio", icon: "🏠" },
    { id: "camino", label: "Mi camino", icon: "🧭" },
    { id: "catalog", label: "Universidades", icon: "🎓" },
    { id: "needs", label: "Recruiting Needs", icon: "📋" },
    { id: "plan", label: "Mi plan de hoy", icon: "✅" },
    { id: "calendar", label: "Calendario", icon: "📅" },
    { id: "history", label: "Mis envíos", icon: "📨" },
    {
      id: "resources", label: "Recursos", icon: "📚",
      children: [
        { id: "eligibility", label: "Elegibilidad", icon: "✅" },
        { id: "video", label: "Tu video", icon: "🎬" },
        { id: "money", label: "Becas y costos", icon: "💵" },
        { id: "exams", label: "Exámenes", icon: "📝" },
        { id: "gpa", label: "Conversor GPA", icon: "🔢" },
        { id: "careers", label: "Buscar por carrera", icon: "🎯" },
        { id: "chequeo", label: "Chequeo trimestral", icon: "🗓️" },
        { id: "familia", label: "Para tu familia", icon: "👨‍👩‍👧" },
        { id: "glosario", label: "Glosario", icon: "📖" },
      ],
    },
  ];
  // Recursos se despliega hacia abajo. Se abre solo cuando se llega a Recursos o a cualquiera de sus
  // secciones (por ejemplo desde un paso de "Empezá acá"), y se puede cerrar a mano sin cambiar de página.
  const RESOURCE_STAGES = ["resources", "eligibility", "exams", "gpa", "careers", "glosario", "chequeo", "familia"];
  const [resourcesOpen, setResourcesOpen] = useState(false);
  useEffect(() => { if (RESOURCE_STAGES.includes(stage)) setResourcesOpen(true); }, [stage]);
  const toggleResources = () => {
    if (resourcesOpen) { setResourcesOpen(false); return; }
    setResourcesOpen(true);
    if (!RESOURCE_STAGES.includes(stage)) { setStage("resources"); window.scrollTo(0, 0); }
    // el menú móvil queda abierto: la persona todavía tiene que elegir una sección
  };

  return (
    <div className={`rm-root rm-has-sidebar ${sidebarCollapsed ? "sidebar-collapsed" : ""} ${menuOpen ? "sidebar-mobile-open" : ""}`}>
      <style>{CSS}</style>
      <div className="rm-bg-blur" style={{ backgroundImage: `url(${BG_SPORTS_IMAGE})` }} />

      {/* Sidebar lateral izquierdo */}
      <aside className="rm-sidebar">
        <div className="rm-sidebar-top">
          <div className="rm-sidebar-logo" onClick={() => { setStage("landing"); setMenuOpen(false); }}>
            <img src="/img/logo.png" alt="Smartrecruit" width="64" height="64" />
            <span className="rm-sidebar-brand">Smartrecruit</span>
          </div>
          <button className="rm-sidebar-toggle" onClick={() => setSidebarCollapsed(!sidebarCollapsed)} aria-label="Expandir/comprimir menú" title="Expandir/comprimir">
            {sidebarCollapsed ? "»" : "«"}
          </button>
        </div>
        <nav className="rm-sidebar-nav">
          {NAV_LINKS.map((l) => l.children ? (
            <React.Fragment key={l.id}>
              <button
                className={`rm-sidebar-link ${stage === l.id ? "active" : ""} ${l.children.some((c) => c.id === stage) ? "has-active" : ""}`}
                onClick={toggleResources}
                aria-expanded={resourcesOpen}
                aria-controls="rm-nav-resources"
                title={l.label}
              >
                <span className="rm-sidebar-icon">{l.icon}</span>
                <span className="rm-sidebar-label">{l.label}</span>
                <svg className={`rm-sidebar-chevron ${resourcesOpen ? "open" : ""}`} width="12" height="12" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M5 7.5l5 5 5-5" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" /></svg>
              </button>
              <div id="rm-nav-resources" className={`rm-nav-sub ${resourcesOpen ? "open" : ""}`} role="group" aria-label={l.label}>
                <div className="rm-nav-sub-inner">
                  {l.children.map((c) => (
                    <button
                      key={c.id}
                      className={`rm-sidebar-link sub ${stage === c.id ? "active" : ""}`}
                      onClick={() => { setStage(c.id); window.scrollTo(0, 0); setMenuOpen(false); }}
                      title={c.label}
                    >
                      <span className="rm-sidebar-icon">{c.icon}</span>
                      <span className="rm-sidebar-label">{c.label}</span>
                    </button>
                  ))}
                </div>
              </div>
            </React.Fragment>
          ) : (
            <button
              key={l.id}
              className={`rm-sidebar-link ${stage === l.id ? "active" : ""}`}
              onClick={() => { setStage(l.id); window.scrollTo(0, 0); setMenuOpen(false); }}
              title={l.label}
            >
              <span className="rm-sidebar-icon">{l.icon}</span>
              <span className="rm-sidebar-label">{l.label}</span>
            </button>
          ))}
        </nav>
        <div className="rm-sidebar-foot">
          <AccountMenu session={session} />
          <button
            className={`rm-sidebar-link ${stage === "profile" ? "active" : ""}`}
            onClick={() => { setStage("profile"); window.scrollTo(0, 0); setMenuOpen(false); }}
            title="Mi perfil"
          >
            <span className="rm-sidebar-icon">👤</span>
            <span className="rm-sidebar-label">Mi perfil</span>
          </button>
        </div>
      </aside>

      {/* Overlay para cerrar el sidebar en mobile */}
      <div className="rm-sidebar-overlay" onClick={() => setMenuOpen(false)} />

      <div className="rm-main">
        {/* Topbar mínimo: hamburguesa (mobile) + ticker */}
        <div className="rm-topbar">
          <button className="rm-topbar-burger" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menú">☰</button>
          <div className="rm-ticker">
            <span className="rm-live-dot"><span></span>EN VIVO</span>
          </div>
        </div>

      <React.Fragment key={dataVersion}>
      {profile && !(profile.consent && profile.consent.version === LEGAL_VERSION && consentIsValid(profile.consent)) && !["form", "terms", "privacy", "about"].includes(stage) && (
        <div className="rm-wrap" style={{ paddingTop: 16 }}>
          <div className="rm-alert">
            <b>Sumamos Términos y Condiciones y Política de Privacidad.</b> Para seguir usando tu perfil, revisalos y aceptalos
            {" "}(si sos menor de 18, con la conformidad de tu madre, padre o tutor). <button type="button" className="rm-btn-inline" onClick={() => { setStage("form"); window.scrollTo(0, 0); }}>Revisar y aceptar →</button>
          </div>
        </div>
      )}
      {stage === "landing" && (
        <>
          {profile ? (
            <DailyPanel profile={profile} setStage={(st) => { setStage(st); window.scrollTo(0, 0); }} saveProfile={saveProfile} dataAsOf={dataAsOf} />
          ) : (
          <div className="rm-hero">
            <div className="rm-wrap rm-hero-inner">
              <h1 className="rm-condensed">Conseguí tu beca <span>por tu propia cuenta</span>, con datos reales.</h1>
              <p>Te mostramos qué universidades buscan tu posición y con cuáles tenés más chances.</p>
              <button className="rm-btn" onClick={() => setStage("start")}>Empezar en 10 minutos →</button>
            </div>
          </div>
          )}

          {!profile && <DemoVideo />}
          <OnboardingPanel profile={profile} setStage={setStage} />
          <OpportunitiesBoard profile={profile} />
        </>
      )}

      {stage === "roadmap" && <RoadmapPage profile={profile} setStage={setStage} />}
      {stage === "camino" && <CaminoPage profile={profile} setStage={setStage} />}
      {stage === "glosario" && <GlossaryPage setStage={setStage} />}
      {stage === "familia" && <FamilyPage profile={profile} setStage={setStage} />}
      {stage === "chequeo" && <QuarterlyPage profile={profile} setStage={setStage} onWrite={(u, kind) => { setOutreachPick({ university: u, kind: kind || "checkin", nonce: Date.now() }); setStage("outreach"); window.scrollTo(0, 0); }} />}
      {stage === "start" && <StartPage setStage={setStage} onDone={(p) => { saveProfile(p); setStage("firstmail"); window.scrollTo(0, 0); }} />}
      {stage === "firstmail" && (profile ? <FirstMailPage profile={profile} setStage={setStage} onOpenSchool={openSchool} onWrite={(u) => { setOutreachPick({ university: u, kind: "first", nonce: Date.now() }); setStage("outreach"); window.scrollTo(0, 0); }} /> : <StartPage setStage={setStage} onDone={(p) => { saveProfile(p); setStage("firstmail"); window.scrollTo(0, 0); }} />)}
      {stage === "outreach" && <MailPage profile={profile} setStage={setStage} initialPick={outreachPick} />}
      {stage === "mylist" && <MyListPage setStage={setStage} onOpenSchool={openSchool} />}
      {stage === "catalog" && <CatalogPage onOpenSchool={openSchool} />}
      {stage === "school" && selectedSchool && <SchoolProfilePage school={selectedSchool} onBack={() => setStage("catalog")} profileMajor={profile?.major} />}
      {stage === "needs" && <RecruitingNeedsPage />}
      {stage === "eligibility" && <EligibilityPage />}
      {stage === "video" && <VideoGuidePage />}
      {stage === "money" && <MoneyGuidePage />}
      {stage === "plan" && <PlanPage profile={profile} setStage={setStage} />}
      {stage === "baja" && <BajaPage setStage={setStage} />}
      {stage === "calendar" && <CalendarPage />}
      {stage === "history" && <OutreachHistoryPage profile={profile} setStage={setStage} />}
      {stage === "exams" && <ExamsPage setStage={setStage} />}
      {stage === "gpa" && <GpaCalculatorPage />}
      {stage === "careers" && <CareerFinderPage profile={profile} onOpenSchool={openSchool} />}
      {stage === "resources" && <ResourcesPage />}
      {stage === "form" && <ProfileForm initial={profile} onSubmit={(p) => { saveProfile(p); setStage("results"); window.scrollTo(0, 0); }} />}
      {stage === "profile" && (profile ? <ProfilePage profile={profile} setStage={setStage} onOpenSchool={openSchool} /> : <ProfileForm onSubmit={(p) => { saveProfile(p); setStage("profile"); window.scrollTo(0, 0); }} />)}
      {stage === "results" && profile && <Results profile={profile} onBack={() => setStage("profile")} onOpenSchool={openSchool} />}
      {stage === "terms" && <TermsPage />}
      {stage === "privacy" && <PrivacyPage />}
      {stage === "about" && <AboutPage setStage={setStage} />}
      <LegalFooter setStage={setStage} />
      </React.Fragment>
      </div>
    </div>
  );
}

function normalizeProfile(p) {
  const gpa4 = GPA_SCALES[p.gpaScale].convert(parseFloat(p.gpaRaw));
  return { ...p, gpa4: Math.round(gpa4 * 100) / 100 };
}

// ---- Modo familia: qué es el proceso, en palabras simples, para madre, padre o tutor (y un resumen del avance para compartir) ----
const FAMILY_STAGE_TEXT = {
  base: "Es la etapa de preparar la base: cuidar las notas, entrenar y entender cómo funciona el sistema. No hay apuro por escribir a muchos entrenadores.",
  visibilidad: "Es la etapa de mostrarse: tener un video corto y las estadísticas al día, armar una lista corta de universidades y mandar los primeros mails.",
  contacto: "Es la etapa en la que los entrenadores de D1 ya pueden escribir: toca escribir seguido, hacer seguimiento y contestar rápido.",
  decision: "Es la etapa de decidir: responder a cada entrenador, comparar ofertas y costos y dejar los documentos listos.",
  ingreso: "Ya se acerca la primera temporada. A partir de la admisión, la universidad les indica los trámites que siguen.",
};
function FamilyPage({ profile, setStage }) {
  const [copied, setCopied] = useState(false);
  const now = new Date();
  const stage = profile ? planStageFor(profile, now) : null;
  const entries = profile ? Object.values(readOutreachLog() || {}) : [];
  const replied = entries.filter((e) => ["respondio", "visita", "oferta"].includes(e.status)).length;
  const offers = entries.filter((e) => e.status === "oferta").length;
  const favs = profile ? readFavorites().length : 0;
  const summary = profile ? quarterlySummaryText(profile, now) : "";
  const copy = () => {
    const done = () => { setCopied(true); setTimeout(() => setCopied(false), 2500); };
    try { navigator.clipboard.writeText(summary).then(done, () => {}); } catch (e) {
      try { const ta = document.createElement("textarea"); ta.value = summary; document.body.appendChild(ta); ta.select(); document.execCommand("copy"); ta.remove(); done(); } catch (err) { /* nada */ }
    }
  };
  return (
    <div className="rm-wrap" style={{ paddingTop: 40, paddingBottom: 60, maxWidth: 820 }}>
      <h2 className="rm-condensed">Para tu familia</h2>
      <p className="rm-hint">Una guía en palabras simples para madre, padre o tutor: cómo funciona el camino a una beca deportiva en EE.UU., qué mirar y cómo acompañar sin hacer el trabajo de la atleta. Pasale este enlace: <b>smartrecruit.com.ar/familia</b>.</p>
      {profile && (
        <div className="rm-college-profile" style={{ marginBottom: 14, padding: "14px 18px" }}>
          <b>Cómo va {(profile.name || "").trim().split(/\s+/)[0] || "la atleta"}</b>
          <p style={{ margin: "8px 0" }}>Etapa: <b>{stage.label}</b>{stage.monthsLeft ? ` (faltan unos ${stage.monthsLeft} meses para el ingreso, temporada ${getEntryYear(profile)})` : ""}. {FAMILY_STAGE_TEXT[stage.key] || ""}</p>
          <p style={{ margin: "8px 0" }}>Escribió a <b>{entries.length}</b> entrenador{entries.length === 1 ? "" : "es"}; le respondieron <b>{replied}</b>{offers ? `; tiene ${offers} oferta${offers === 1 ? "" : "s"}` : ""}. Su lista tiene <b>{favs}</b> universidad{favs === 1 ? "" : "es"}.</p>
          <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
            <button type="button" className="rm-btn-inline" onClick={copy}>{copied ? "¡Copiado!" : "Copiar resumen →"}</button>
            <a className="rm-btn-inline" href={`https://wa.me/?text=${encodeURIComponent(summary)}`} target="_blank" rel="noopener noreferrer">Enviar por WhatsApp →</a>
          </div>
        </div>
      )}
      <GuideBlock title="Qué es Smartrecruit y qué no es" open>
        <p>Smartrecruit es una <b>guía educativa</b>: enseña cómo funciona el reclutamiento universitario en EE.UU. y ordena los pasos para que la atleta se postule por su cuenta.</p>
        <p><b>No es una agencia ni un intermediario, no garantiza becas ni admisiones y no cobra</b> por conseguirlas. Tampoco está afiliada a la NCAA, la NAIA, la NJCAA ni a ninguna universidad.</p>
      </GuideBlock>
      <GuideBlock title="Cómo es el camino, en cuatro etapas">
        <p><b>1. Base.</b> {FAMILY_STAGE_TEXT.base}</p>
        <p><b>2. Visibilidad.</b> {FAMILY_STAGE_TEXT.visibilidad}</p>
        <p><b>3. Contacto.</b> {FAMILY_STAGE_TEXT.contacto}</p>
        <p><b>4. Decisión.</b> {FAMILY_STAGE_TEXT.decision}</p>
        <p>Es un camino de varios años: lo que más ayuda es la constancia (un paso por semana) y no dejar enfriar a los entrenadores que ya contestaron.</p>
      </GuideBlock>
      <GuideBlock title="Cuánto puede cubrir una beca">
        <p>La "beca total" casi nunca es solo deportiva: suele ser una <b>combinación</b> de beca deportiva, beca por notas y ayuda de la propia universidad. En divisiones como D2 o NAIA las becas suelen ser parciales, y D3 no da becas deportivas (sí ayuda académica).</p>
        <p>Los estudiantes internacionales <b>no pueden recibir la ayuda federal de EE.UU.</b> Lo que sí pueden recibir es la ayuda de cada universidad.</p>
        <p><button type="button" className="rm-btn-inline" onClick={() => { setStage("money"); window.scrollTo(0, 0); }}>Ver "Becas y costos" completo →</button></p>
      </GuideBlock>
      <GuideBlock title="Qué mirar antes de aceptar una oferta">
        <p>Pidan siempre la oferta <b>por escrito</b> y antes de decidir fíjense en: qué cubre (matrícula, alojamiento, comidas, seguro médico y otros gastos), por cuántos años es, cómo se renueva y hasta qué fecha hay que responder.</p>
        <p>Sumen los gastos que la beca no cubre (pasajes, seguro, libros, gastos personales) y comparen con lo que la familia puede pagar. Un compromiso verbal no obliga, pero lo que se firma sí: lean cada documento en familia antes de firmar.</p>
      </GuideBlock>
      <GuideBlock title="Señales de alerta">
        <p>Desconfíen de quien <b>garantice</b> una beca, presione para decidir ya o pida dinero por adelantado a cambio de "conseguirla". Nadie puede asegurar una beca antes de que un entrenador y la universidad la ofrezcan por escrito.</p>
        <p>Tampoco compartan datos sensibles (pasaporte, cuentas bancarias) por mail con alguien que todavía no es una universidad o un entrenador verificado. Ante la duda, comprueben el mail del entrenador en la página oficial del equipo.</p>
      </GuideBlock>
      <GuideBlock title="Cómo acompañar sin hacer el trabajo por ella">
        <p>Los entrenadores quieren hablar con la atleta: conviene que escriba ella sus mails, con su voz. La familia puede ayudar mucho con tres cosas:</p>
        <p>• <b>Tiempo y constancia:</b> acordar un momento fijo por semana para su plan y para el chequeo del trimestre.<br />• <b>Documentos:</b> pasaporte vigente, certificados de estudios traducidos y el examen de inglés. Después de la admisión, la universidad indica el resto.<br />• <b>Plata:</b> hablar con franqueza de cuánto puede aportar la familia, para comparar ofertas con números reales.</p>
        {profile && profile.consent && profile.consent.minor && <p>Como la atleta es menor de 18, Smartrecruit pide la conformidad de un adulto con su nombre y correo. Pueden revisar o corregir esos datos desde el perfil.</p>}
        <p><button type="button" className="rm-btn-inline" onClick={() => { setStage("chequeo"); window.scrollTo(0, 0); }}>Hacer juntos el chequeo del trimestre →</button></p>
      </GuideBlock>
      {!profile && <p className="rm-hint">Si la atleta todavía no armó su perfil, <button type="button" className="rm-btn-inline" onClick={() => setStage("start")}>puede empezar acá →</button></p>}
    </div>
  );
}

// ---- Página del chequeo del trimestre ----
function QuarterlyPage({ profile, setStage, onWrite }) {
  const [q, setQ] = useState(readQuarterly);
  const [ticks, setTicks] = useState({});
  const [copied, setCopied] = useState(false);
  const [finished, setFinished] = useState(false);
  useEffect(() => { ensureQuarterlySince(); }, []);
  if (!profile) {
    return (
      <div className="rm-wrap" style={{ paddingTop: 40, paddingBottom: 60 }}>
        <h2 className="rm-condensed">Chequeo del trimestre</h2>
        <p className="rm-hint">Primero armá tu perfil: el chequeo se hace sobre tus notas, tus mails y tu lista.</p>
        <button className="rm-btn" onClick={() => setStage("start")}>Armar mi perfil →</button>
      </div>
    );
  }
  const now = new Date();
  const status = quarterlyStatus(profile, now);
  const entries = Object.values(readOutreachLog() || {});
  const cold = coldCoaches(entries).slice(0, 6);
  const replied = entries.filter((e) => ["respondio", "visita", "oferta"].includes(e.status)).length;
  const offers = entries.filter((e) => e.status === "oferta").length;
  const favs = readFavorites().length;
  const checkins = readJSON("rr_checkins", []);
  const lastCk = checkins.length ? checkins[checkins.length - 1] : null;
  const stage = planStageFor(profile, now);
  const nextStage = planNextStage(profile, now);
  let eligPending = 0;
  try { const checked = readJSON("rr_eligibility_checklist", {}); const elig = ELIGIBILITY_CHECKLISTS[Object.keys(ELIGIBILITY_CHECKLISTS)[0]] || []; eligPending = elig.filter((i) => !checked[i.id]).length; } catch (e) { /* nada */ }
  const fmt = (d) => d.toLocaleDateString("es-AR", { day: "numeric", month: "long", year: "numeric" });
  const items = [
    { id: "notas", title: "1. Notas y perfil", text: `Promedio cargado: ${profile.gpaRaw || "—"} (${profile.gpa4 || "—"} en escala 4.0). Si cerró un trimestre o un semestre, cargá el nuevo. Revisá también altura, peso, posición y año de egreso.`, cta: "Actualizar perfil", run: () => setStage("form") },
    { id: "video", title: "2. Estadísticas y video", text: lastCk ? `Tu último check-in fue hace ${daysSince(lastCk.date)} días. Sumá lo último de la temporada a tus números y a tu video: tus próximos mails los usan.` : "Todavía no hiciste ningún check-in. Cargá tus números y el link a tu último partido: tus mails los usan.", cta: "Hacer el check-in", run: () => setStage("landing") },
    { id: "coaches", title: "3. Coaches sin novedades", text: cold.length ? `${cold.length === 1 ? "Hay 1 coach" : `Hay ${cold.length} coaches`} sin recibir nada tuyo hace 2 meses o más. Un check-in corto con tus novedades los vuelve a poner sobre la mesa.` : `No tenés coaches fríos. Este trimestre sumá 2 o 3 programas nuevos a tu lista de envíos.`, cta: cold.length ? null : "Buscar universidades", run: () => setStage("catalog"), extra: (
      <>
        <p className="rm-hint" style={{ margin: "6px 0" }}>Hasta hoy: escribiste a {entries.length}, te respondieron {replied}{offers ? ` y tenés ${offers} oferta${offers === 1 ? "" : "s"}` : ""}.</p>
        {cold.map((e) => (
          <div key={e.university} style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", margin: "4px 0" }}>
            <span style={{ flex: "1 1 220px" }}><b>{e.university}</b> · hace {daysSince(e.lastContact)} días · {(OUTREACH_STATUS_LABELS[e.status] || e.status || "").toLowerCase()}</span>
            <button type="button" className="rm-btn-inline" onClick={() => onWrite(e.university, "checkin")}>Escribir check-in →</button>
          </div>
        ))}
      </>
    ) },
    { id: "lista", title: "4. Tu lista de universidades", text: `Tu lista tiene ${favs} universidad${favs === 1 ? "" : "es"}. Lo ideal es tener entre 10 y 15, mezclando aspiracionales, realistas y seguras.`, cta: "Ver mi lista", run: () => setStage("mylist") },
    { id: "resultados", title: "5. Tus resultados", text: "Los resultados cambian cuando los coaches publican búsquedas nuevas. Volvé a mirarlos y sumá lo que aparezca.", cta: "Ver mis resultados", run: () => setStage("results") },
    { id: "camino", title: "6. Tu etapa", text: `Estás en la etapa ${stage.label}${nextStage ? `; la próxima, ${nextStage.label}, empieza en unos ${nextStage.months} meses` : ""}. ${stage.focus}`, cta: "Ver Mi camino", run: () => setStage("camino") },
    { id: "elig", title: "7. Elegibilidad y exámenes", text: eligPending ? `Te quedan ${eligPending} ítem${eligPending === 1 ? "" : "s"} sin marcar en la checklist de elegibilidad. Revisá también la fecha de tu examen de inglés.` : "Tu checklist de elegibilidad está completa. Revisá igual la fecha de tu examen de inglés y los documentos.", cta: "Ir a Elegibilidad", run: () => setStage("eligibility") },
  ];
  const doneCount = items.filter((i) => ticks[i.id]).length;
  const copy = () => {
    const text = quarterlySummaryText(profile, now);
    const done = () => { setCopied(true); setTimeout(() => setCopied(false), 2500); };
    try { navigator.clipboard.writeText(text).then(done, () => {}); } catch (e) {
      try { const ta = document.createElement("textarea"); ta.value = text; document.body.appendChild(ta); ta.select(); document.execCommand("copy"); ta.remove(); done(); } catch (err) { /* nada */ }
    }
  };
  const finish = () => {
    const next = { ...q, done: [...q.done, new Date().toISOString()].slice(-12) };
    writeJSON("rr_quarterly", next); setQ(next); setFinished(true); window.scrollTo(0, 0);
  };
  const nextDate = new Date(Date.now() + QUARTER_DAYS * 86400000);
  const box = { background: "#fff", border: "1px solid #e3ded2", borderRadius: 8, padding: 16, marginBottom: 12 };
  return (
    <div className="rm-wrap" style={{ paddingTop: 40, paddingBottom: 60, maxWidth: 820 }}>
      <h2 className="rm-condensed">Chequeo del trimestre</h2>
      <p className="rm-hint">Cada 3 meses, 10 minutos para que tu proceso no se enfríe. Son 4 o 5 años de camino: lo que se revisa seguido no se pierde.</p>
      <p className="rm-hint">{status.lastDone ? `Último chequeo: ${fmt(status.lastDone)}.` : "Todavía no hiciste ningún chequeo."}{status.due ? " Ya toca hacer uno." : status.days !== null ? ` Falta${QUARTER_DAYS - status.days === 1 ? "" : "n"} ${Math.max(0, QUARTER_DAYS - status.days)} día${QUARTER_DAYS - status.days === 1 ? "" : "s"} para el próximo, pero podés hacerlo cuando quieras.` : ""}</p>
      {finished && (
        <div className="rm-alert" style={{ background: "#E8F5EC", borderColor: "#2e8b57", color: "#1c5a37" }}>
          <b>Chequeo guardado.</b> El próximo toca alrededor del {fmt(nextDate)}. Te lo vamos a recordar en tu plan y en el mail semanal.
        </div>
      )}
      <p className="rm-hint"><b>{doneCount} de {items.length}</b> revisados</p>
      {items.map((it) => (
        <div key={it.id} style={box}>
          <label style={{ display: "flex", gap: 10, alignItems: "flex-start", cursor: "pointer" }}>
            <input type="checkbox" checked={!!ticks[it.id]} onChange={() => setTicks((t) => ({ ...t, [it.id]: !t[it.id] }))} style={{ marginTop: 4 }} />
            <span><b>{it.title}</b><br /><span style={{ fontSize: 14 }}>{it.text}</span></span>
          </label>
          {it.extra && <div style={{ marginLeft: 26 }}>{it.extra}</div>}
          {it.cta && <div style={{ marginLeft: 26, marginTop: 8 }}><button type="button" className="rm-btn-inline" onClick={it.run}>{it.cta} →</button></div>}
        </div>
      ))}
      <div style={box}>
        <b>Para compartir con tu familia</b>
        <p className="rm-hint" style={{ margin: "6px 0 10px" }}>Copiá un resumen corto (etapa, promedio, coaches y próximo paso) para pasárselo a tu familia o a tu entrenador.</p>
        <button type="button" className="rm-btn-inline" onClick={copy}>{copied ? "¡Copiado!" : "Copiar resumen →"}</button>
        {" "}<button type="button" className="rm-btn-inline" onClick={() => { setStage("familia"); window.scrollTo(0, 0); }}>Ver la página para tu familia →</button>
      </div>
      <button type="button" className="rm-btn" onClick={finish} disabled={finished}>{finished ? "Chequeo guardado ✓" : "Terminé el chequeo"}</button>
      {finished && <> <button type="button" className="rm-btn-inline" style={{ marginLeft: 12 }} onClick={() => { setStage("landing"); window.scrollTo(0, 0); }}>Volver al inicio →</button></>}
    </div>
  );
}

// La app espera a que los datos estén cargados; mientras tanto se ve una pantalla liviana (el código pesa ~1 MB, los datos se bajan en paralelo).
function DataSplash({ error, onRetry }) {
  return (
    <div style={{ minHeight: "100vh", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 14, background: "#0C2340", color: "#fff", fontFamily: "Inter, system-ui, sans-serif", textAlign: "center", padding: 24 }}>
      <img src="/img/logo.png" alt="Smartrecruit" width="72" height="72" style={{ borderRadius: 14, background: "#fff" }} />
      {error ? (
        <>
          <div style={{ fontSize: 16 }}>No pudimos cargar los datos. Revisá tu conexión.</div>
          <button type="button" onClick={onRetry} style={{ padding: "10px 18px", borderRadius: 10, border: 0, fontWeight: 700, cursor: "pointer" }}>Reintentar</button>
        </>
      ) : (
        <div style={{ fontSize: 15, opacity: 0.85 }}>Cargando universidades y coaches…</div>
      )}
    </div>
  );
}

export default function App() {
  const [state, setState] = useState("loading");
  const start = () => { setState("loading"); loadData().then(() => setState("ready")).catch(() => setState("error")); };
  const isAthleteLink = typeof window !== "undefined" && /^\/atleta\/?$/.test(window.location.pathname);
  useEffect(() => { if (!isAthleteLink) start(); }, []);
  const [wantsStart, setWantsStart] = useState(false);
  if (isAthleteLink) return <AthleteCardPage />;
  if (state !== "ready") {
    // Visitante nuevo en la portada: se muestra el título y el botón ya, sin esperar los datos (la portada completa entra apenas terminan de cargar).
    let isNewVisitor = false;
    try { isNewVisitor = window.location.pathname === "/" && !localStorage.getItem("rr_profile"); } catch (e) {}
    if (state === "error" || !isNewVisitor) return <DataSplash error={state === "error"} onRetry={start} />;
    return (
      <div className="rm-root">
        <style>{CSS}</style>
        <div className="rm-hero">
          <div className="rm-wrap rm-hero-inner">
            <h1 className="rm-condensed">Conseguí tu beca <span>por tu propia cuenta</span>, con datos reales.</h1>
            <p>Te mostramos qué universidades buscan tu posición y con cuáles tenés más chances.</p>
            <button className="rm-btn" disabled={wantsStart} onClick={() => { setWantsStart(true); try { window.history.pushState({ stage: "start" }, "", "/start"); } catch (e) {} }}>
              {wantsStart ? "Cargando datos…" : "Empezar en 10 minutos →"}
            </button>
          </div>
        </div>
      </div>
    );
  }
  return <AppInner />;
}
